(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-fp8-attn-video"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-1\">一 · 一个线上事故：分辨率上调之后，注意力把整条链路拖垮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-2\">二 · 它解决什么：只动注意力路径的 Q/K/V 与 P</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-3\">三 · 它不解决什么：三类边界必须提前划清</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-4\">四 · 适用判据：什么时候该换、什么时候不该换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-5\">五 · 事故复盘落到内核参数上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-6\">六 · 尖峰塌缩与展平错位：FP8 时空注意力内核的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-7\">七 · QKV 投影后的按头切分与行级缩放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-8\">八 · 沿时间-空间展平序列的分块流式加载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-9\">九 · FP8 MMA 上的 QK^T 与在线 softmax 更新</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-10\">十 · P 量化到 E4M3 与 FP8 PV 乘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-11\">十一 · 输出反缩放与写回 BF16</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-12\">十二 · 分块流水线上的四道坎：FP8 时空注意力在 SM100 上的失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-13\">十三 · 得分公式的逐项拆解：缩放因子为何放在FP8乘法之外</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-14\">十四 · 在线 softmax 的 running 更新：分块之间的状态只有三个标量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-15\">十五 · P 的量化与 PV 乘：为什么累加器必须是 FP32</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-16\">十六 · 伪代码：把公式落到 SM100 的块循环上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-17\">十七 · 展平顺序与访存合并：公式之外的第四个约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-18\">十八 · 失效边界：P 量化尖峰、展平顺序与 SMEM 占用的三重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-19\">十九 · 请求形态：什么样的前向才吃得到 FP8 的红利</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-20\">二十 · 长度分布：批内序列长度方差决定分块调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-21\">二十一 · 并发与批大小：头数、分块与 SM 占用三者互相牵制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-22\">二十二 · 负载不对时的第一类崩塌：P 量化误差在尖峰处放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-23\">二十三 · 负载不对时的第二类崩塌：展平顺序破坏访存合并</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-24\">二十四 · 负载配方的工程判断：先定形态，再定批，最后定回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-25\">二十五 · 硬件档位：从单卡 SM100 到 NVL72 机柜的注意力落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-26\">二十六 · 并行拓扑：头并行优先，序列并行兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-27\">二十七 · 量化方案：E4M3 为主干，尖峰通道留高精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-28\">二十八 · KV 策略：分块驻留与展平顺序绑定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-29\">二十九 · 调度参数：批、分块、occupancy 的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-30\">三十 · 可复现的配置思路：从容量不等式倒推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-31\">三十一 · 配置边界：FP8 时空注意力内核的失效条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-32\">三十二 · 显存账本：O(N²) 消失之后，谁成了新的地板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-33\">三十三 · 带宽与访存合并：展平顺序决定吞吐上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-34\">三十四 · 通信：分离式部署下注意力内核的接口成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-35\">三十五 · 功耗与占用率：FP8 MMA 兑现不了的两个前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-36\">三十六 · 尾延迟：尖峰从哪里来，往哪里压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-37\">三十七 · 规模上去以后，崩的顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-38\">三十八 · 规模上去以后，先崩的是带宽而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-39\">三十九 · 数值边界：尖峰处的量化误差与回退代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-40\">四十 · 通信与尾延迟：并行切分后的新瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-41\">四十一 · 精度失败的三条路径与可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-42\">四十二 · OOM的真实来源：不是权重，是分块与副本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-43\">四十三 · 批抖动与路由不均：调度层的两类噪声</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-44\">四十四 · 尾延迟尖刺的定位：分块边界与跨帧展平</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-45\">四十五 · 监控体系与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-46\">四十六 · 失败模式与配置项的对应表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-47\">四十七 · 同族算法的四条分界线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-48\">四十八 · 决策表：按约束选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-49\">四十九 · 适用条件的量化判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-50\">五十 · 组合与互斥：三条工程规则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-51\">五十一 · 一个选型实例的推演</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-52\">五十二 · 选型的收敛判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-attn-video-sec-53\">五十三 · 同族算法怎么选：FP8时空注意力的适用边界与失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:485px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 484.7 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"402.7\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">潜变量经QKV投影后按头切分，Q/K按行最大值缩放至E4M3</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"402.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按FlashAttention式分块沿时间-空间展平序列流式加载K/V块</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"402.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">QK^T在FP8 MMA上计算，softmax在线更新running ma…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"402.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">P量化为E4M3后与V做FP8 PV乘，累加器FP32</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"402.7\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出反缩放写回BF16供后续MLP与残差使用</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-fp8-attn-video-sec-1\">一 · 一个线上事故：分辨率上调之后，注意力把整条链路拖垮</h3>\n<p>某条视频生成服务在灰度中把输出分辨率与帧数同时上调，模型结构、权重、采样步数都没动，唯独时空注意力的序列长度变了。序列长度 N 随分辨率与帧数平方增长，BF16 路径下 QK^T 与 PV 两个矩阵乘迅速取代卷积与 MLP，成为单步时延与峰值显存的双重瓶颈。事故的表征很有欺骗性：单帧短片段仍然正常，一旦进入长视频档位，单步注意力时延抬升到挤占整个去噪循环的预算，峰值显存把并发批挤到 1，尾延迟击穿 SLO；更糟的是分块边界处出现周期性卡顿，采样器每跨过一个时间块就抖一次。运维侧第一反应是加卡、降并发，但问题不在算力总量，而在注意力路径上显存随 N² 增长、带宽被 K/V 流式加载吃满这两件事同时发生。这正是 FP8 时空注意力内核要处理的场景：不是把模型改小，而是把注意力这一段从 BF16 的时延与显存双重约束里解放出来。</p>\n<p>把事故拆成可度量的量：BF16 下注意力需要为每个头物化 N×N 的得分矩阵或至少承担其带宽代价，显存占用随 N² 增长；QK^T 与 PV 的浮点吞吐直接决定单步时延。当 N 翻倍，QK^T 的计算量与得分矩阵的显存需求同步放大，而 HBM 带宽不变，于是内核从计算受限滑向带宽受限。工程判断的分水岭在这里：如果注意力占单步时延的比例已经压过线性层，那么优化线性层权重精度的收益被注意力稀释；必须单独对注意力路径下手。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-2\">二 · 它解决什么：只动注意力路径的 Q/K/V 与 P</h3>\n<p>本算法的适用面被刻意收窄：它量化的是注意力路径上的 Q、K、V 与 softmax 后的 P 矩阵，把它们以 FP8 E4M3 存储并送进 FP8 MMA，PV 累加保持 FP32，输出反缩放写回 BF16 供后续 MLP 与残差使用。它不改模型结构、不动线性层权重、不引入新的训练或蒸馏环节，因此可以作为 BF16 注意力内核的直接替换件上线。这一点必须与相邻条目分清：NVFP4 视频 DiT 量化作用于线性层权重，解决的是另一段瓶颈；本算法只对注意力这一段负责，两者可以叠加，但不能互相替代。</p>\n<p>它真正解决的是三件事的耦合：显存、吞吐、数值稳定。显存侧，按 FlashAttention 式分块沿时间-空间展平序列流式加载 K/V 块，不再物化完整得分矩阵，注意力显存从 O(N²) 降到 O(N)；吞吐侧，QK^T 与 PV 走 FP8 MMA，FP8 使这两段吞吐翻倍；数值侧，Q/K 按行最大值缩放至 E4M3 抑制溢出，PV 用 FP32 累加器兜住累加误差。三者缺一不可——只降精度不换分块策略，显存仍是 O(N²)；只做分块不降精度，吞吐红利拿不到。</p>\n<div class=\"formula\">$$O_{i}=\\frac{\\sum_{j}e^{s_{ij}-m_{i}}\\,V_{j}}{\\sum_{j}e^{s_{ij}-m_{i}}},\\quad s_{ij}=\\frac{\\Delta_{q}\\Delta_{k}}{\\sqrt{d}}\\,(\\hat{Q}_{i}\\hat{K}_{j}^{\\top}),\\quad \\text{err}\\propto 2^{-4}\\lVert Q\\rVert\\lVert K\\rVert$$</div>\n<p>公式里 Δ_q、Δ_k 是行级缩放因子，误差项与 2⁻⁴ 及 Q、K 的范数成正比——这是 E4M3 尾数位宽的直接后果，也是后面所有失败模式的根源。分块在线 softmax 的 running 更新必须精确维护，否则分块拼接处会出现权重不归一：</p>\n<div class=\"formula\">$$m^{\\text{new}}=\\max(m,\\ \\max_j s_j),\\quad \\ell^{\\text{new}}=e^{m-m^{\\text{new}}}\\ell+\\sum_j e^{s_j-m^{\\text{new}}}$$</div>\n<p>其中 s_j 为分块内 QK^T 得分，m 与 ℓ 为 running 最大值与归一化因子。工程上这意味着每个 K/V 块加载进来后，必须先更新 m 再重算 ℓ，任何跳过重标定的“优化”都会在长序列上积累成可见的亮度漂移。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-3\">三 · 它不解决什么：三类边界必须提前划清</h3>\n<p>第一类边界是精度边界。P 矩阵量化为 E4M3 后，softmax 尖峰处的量化误差被放大，表现为注意力权重塌缩与细节丢失——模型不是崩掉，而是纹理与运动细节变糊，这种退化在离线指标上不明显，在长视频的人眼评审里却直接可见。缓解手段是保留部分高精度通道或做混合精度回退，代价是这部分通道退回 BF16 吞吐，FP8 的整体收益被按比例削减。若模型的注意力分布本身就极度尖锐（例如强条件控制下的局部编辑），回退比例会上升，收益收窄，这条路径就不该是首选。</p>\n<p>第二类边界是访存边界。跨帧注意力展平顺序不当会破坏 HBM 访存合并，分块加载 K/V 时带宽利用率骤降，长视频分块边界处延迟明显上升——事故里那个周期性卡顿正是这一类。展平顺序必须让同一分块内的 K/V 在地址上连续，时间维与空间维的遍历次序要与分块形状对齐，这不是算法问题而是数据布局问题，却直接决定 FP8 MMA 能不能喂饱。</p>\n<p>第三类边界是规模与占用边界。分块大小受 SMEM 容量限制，分块大小与 SMEM 占用未针对 SM100 调优时，occupancy 过低使 FP8 MMA 吞吐优势无法兑现，甚至慢于 BF16 内核——降精度反而变慢，这是最容易被误判为“FP8 不成熟”的失败模式。序列极长时，单靠本内核仍不够，必须配合长视频分块与重叠策略，把跨块的状态衔接交给外层调度。</p>\n<table class=\"mini\"><thead><tr><th>边界</th><th>触发条件</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>精度</td><td>softmax 尖峰、强局部条件</td><td>细节退化，高精度通道回退削减吞吐收益</td><td>保留高精度通道 / 混合精度回退</td></tr><tr><td>访存</td><td>跨帧展平顺序与分块形状错位</td><td>带宽利用率骤降，分块边界延迟尖刺</td><td>按分块形状重排时间-空间遍历次序</td></tr><tr><td>占用</td><td>分块与 SMEM 未按 SM100 调优</td><td>occupancy 过低，慢于 BF16 内核</td><td>按 SM100 SMEM 容量重定分块</td></tr></tbody></table>\n\n<h3 id=\"alg-fp8-attn-video-sec-4\">四 · 适用判据：什么时候该换、什么时候不该换</h3>\n<p>判据可以写成一条粗粒度的收益不等式：设注意力占单步时延比例为 α，FP8 使 QK 与 PV 吞吐翻倍即该段时延约减半，则单步时延的相对收益约为 α/2；同时显存从 O(N²) 降到 O(N) 释放出的并发额度，是第二重收益。当 α 较小（注意力不是主导），换内核的收益被线性层与卷积稀释，工程上应先处理权重精度那条线；当 α 显著偏大，且分辨率与帧数处于高档位，本算法的收益才立得住。反过来，若序列长度尚短、N² 项还未压过带宽项，BF16 内核的 occupancy 更易做满，强行切 FP8 可能落入第三类边界。</p>\n<p>具体例子：同一套 DiT 在短片段档位下注意力占比低，BF16 内核的时延被卷积与 MLP 掩盖，此时换 FP8 只带来个位数收益却引入回退逻辑的维护成本；而在高分辨率长视频档位，注意力成为单步时延主项，FP8 把 QK 与 PV 吞吐翻倍、显存降到 O(N) 后，并发批得以抬升，SLO 才重新可达。判据的落点是负载配方：请求形态为高分辨率长视频的时空注意力前向，批大小按头数与序列分块配置，SLO 以单步注意力时延与峰值显存衡量——这三个量决定了是否跨过适用门槛。</p>\n<ul><li>该换：注意力占单步时延主项、N² 显存压住并发、SLO 卡在单步注意力时延。</li><li>缓换：注意力占比低、序列尚短、BF16 occupancy 已做满。</li><li>不该单独换：softmax 分布极尖且回退比例高，收益被高精度通道吃掉。</li><li>必须配套：序列极长时与长视频分块重叠策略同用，否则跨块状态衔接仍由外层承担。</li></ul>\n\n<h3 id=\"alg-fp8-attn-video-sec-5\">五 · 事故复盘落到内核参数上</h3>\n<p>回到开头那次灰度：分辨率与帧数上调后，BF16 路径的得分矩阵显存随 N² 增长把并发压到 1，K/V 流式加载吃满带宽使单步时延抬升，分块边界因展平顺序与分块形状错位产生周期性卡顿。三条症状分别对应本算法的三个机制：分块在线 softmax 把显存降到 O(N)，FP8 MMA 把 QK 与 PV 吞吐翻倍，行级缩放与 FP32 累加把数值稳住。但事故也暴露出边界：如果只把 dtype 换成 FP8 而不重排展平顺序，第二类边界照旧触发；如果不按 SM100 的 SMEM 容量重定分块，第三类边界会让内核慢于 BF16，灰度会被误判为回滚。</p>\n<p>因此上线顺序应是：先按分块形状重排时间-空间展平顺序，保证同一分块内 K/V 地址连续；再按 SM100 SMEM 容量定分块大小与占用，确认 FP8 MMA 吞吐兑现；最后才评估 P 矩阵量化在尖峰处的退化，决定高精度通道的保留比例。这个顺序不能颠倒——访存与占用没做对时，精度回退的收益根本无法测量。工程判断落在具体机制上：FP8 时空注意力内核的价值不在“用了 FP8”，而在分块、展平、缩放、累加四件事同时对齐 SM100 的访存与占用约束，任何一件缺位，收益都会从吞吐翻倍退化为一次无效的精度冒险。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-6\">六 · 尖峰塌缩与展平错位：FP8 时空注意力内核的失效边界</h3>\n<p>线上事故的形态往往不是内核报错，而是画面“变干净了”：一段高分辨率长视频在采样到中段时，运动细节突然糊掉，人物边缘出现块状拖影，而日志里没有任何异常。根因通常落在 P 矩阵的量化上。时空注意力沿时间-空间展平后，序列长度随分辨率与帧数平方增长，softmax 得分分布极不均匀——少数跨帧关键 token 占据绝大部分权重，其余接近零。把 P 量化成 E4M3 时，尖峰处的相对误差被分母放大，权重向少数通道塌缩，注意力退化为近似硬选择，细节信息不再被加权聚合。公式给出的误差上界说明了这一点：</p>\n<div class=\"formula\">$$O_{i}=\\frac{\\sum_{j}e^{s_{ij}-m_{i}}\\,V_{j}}{\\sum_{j}e^{s_{ij}-m_{i}}},\\quad s_{ij}=\\frac{\\Delta_{q}\\Delta_{k}}{\\sqrt{d}}\\,(\\hat{Q}_{i}\\hat{K}_{j}^{\\top}),\\quad \\text{err}\\propto 2^{-4}\\lVert Q\\rVert\\lVert K\\rVert$$</div>\n<p>误差正比于 Q、K 的范数与 2^{-4} 的尾数精度，行级缩放只能压住溢出，压不住尖峰处的相对失真。工程上的判断是：当注意力熵明显偏低（跨帧注意力集中在少数 token）时，必须保留部分高精度通道，或对尖峰分块做 BF16 回退，代价是那部分分块的 MMA 吞吐回落到 BF16 水平，整步时延上升。</p>\n<p>第二类失效来自展平顺序。分块流式加载 K/V 依赖 HBM 访存合并，若跨帧展平把时间维与空间维交错得不连续，相邻 token 在显存中不再邻接，每个 K/V 块的有效带宽骤降，长视频分块边界处的延迟明显上升——这正是“分块边界延迟”而非平均延迟恶化的来源。第三类失效是 SMEM 占用与分块大小未针对 SM100 调优：分块过大挤占 SMEM 使 occupancy 过低，FP8 MMA 的吞吐优势无法兑现，内核甚至慢于 BF16 版本；分块过小则在线 softmax 的 running max 与归一化因子更新次数增多，寄存器压力与重算开销吃掉收益。这三类失效共同划出适用边界。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>注意力熵低、尖峰集中</td><td>权重塌缩、细节丢失</td><td>需高精度通道回退，吞吐回落</td></tr><tr><td>跨帧展平不连续</td><td>K/V 加载带宽骤降</td><td>分块边界时延上升</td></tr><tr><td>分块与 SMEM 未调优</td><td>occupancy 不足</td><td>FP8 MMA 优势无法兑现</td></tr></tbody></table>\n<p>它不解决的问题同样明确：本内核只量化注意力路径的 Q/K/V 与 P，不触碰线性层权重，因此对 MLP 与投影主导的时延无收益；它把注意力显存从 O(N^2) 降到 O(N)，但序列极长时仍需配合长视频分块与重叠策略，单靠内核无法突破 SMEM 容量上限；它也不改变模型结构，故对已经因架构设计导致注意力占比很低的模型，替换内核的收益接近于零。判断是否该上这套内核，先看注意力在单步时延中的占比与注意力熵，再看展平顺序能否与显存布局对齐——三者任一不满足，收益就会被上述代价抵消。</p>\n<h3 id=\"alg-fp8-attn-video-sec-7\">七 · QKV 投影后的按头切分与行级缩放</h3>\n<p>注意力内核的入口不是原始潜变量，而是投影后的 Q/K/V 张量。视频 DiT 的潜变量形状通常为 <code>[B, F, H, W, C]</code>，经 QKV 线性层后得到三份同形状输出，再按头数 <code>h</code> 切成 <code>[B·h, N, d]</code>，其中 <code>N = F·H·W</code> 是沿时间-空间展平的序列长度。这一步的代价不在计算而在重排：切分本身是一次带 stride 的视图变换，若头维与序列维在内存中交错，内核读 Q 时会出现跨步访问，HBM 事务数上升。工程上要求投影输出直接以头主序写出，使后续分块加载连续。</p>\n<p>切分完成后立即做行级缩放：对每个头、每个 token 行取 <code>max|Q_i|</code> 与 <code>max|K_j|</code>，把行缩放到 E4M3 可表示范围（最大有限值 448），缩放因子以 FP32 保存。这一步的输入是 BF16 的 Q/K 块，输出是 E4M3 的 Q/K 块加一组行缩放向量。代价是每个 token 一次行归约，相对 QK^T 的 <code>O(N²d)</code> 计算可忽略，但它决定了整个内核的数值上限：E4M3 只有 3 位尾数，行内动态范围压缩后，量化误差按 <code>err ∝ 2^{-4}‖Q‖‖K‖</code> 传播到得分上。缩放因子必须在 PV 输出反缩放时精确配对，否则 Q 与 K 的缩放乘积会引入系统性偏差。</p>\n<p>具体例子：一段 720p、49 帧的视频在 patch 16 下展平后 <code>N</code> 达数万量级，头数取 24 时单头 <code>d=128</code>。若不切分而整块处理，Q 张量驻留显存的需求远超单 SM 的 SMEM 容量；按头切分后每个 CTA 只负责一个头的一段 query 块，SMEM 占用可控。这里的关键判断是：切分粒度必须与后续分块大小联合决定，先定分块再定头映射，而不是反过来。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-8\">八 · 沿时间-空间展平序列的分块流式加载</h3>\n<p>FlashAttention 式分块的核心是把 <code>N×N</code> 的得分矩阵切成 <code>Bq×Bk</code> 的瓦片，外循环遍历 query 块，内循环沿 KV 块流式推进。视频注意力的特殊之处在于展平顺序：<code>N</code> 是 <code>F·H·W</code> 的一维化，若按帧主序展平，同一 KV 块内的 token 在空间上相邻、时间上同帧，访存合并良好；若按空间主序展平，一个 KV 块会横跨多帧，地址跳变导致 HBM 带宽利用率骤降。这是与通用 FlashAttention 的实质差别——通用实现只需保证一维连续性，视频内核必须把展平顺序作为编译期约束固化。</p>\n<p>每一步的输入是 E4M3 的 K/V 块与行缩放向量，输出是载入 SMEM 的瓦片。代价分两部分：一是带宽，每个 KV 块在 query 块外循环中被重复加载 <code>N/Bq</code> 次，总流量为 <code>O(N²d/Bq)</code> 字节，分块越大重复越少但 SMEM 占用越高；二是延迟，SM100 的 SMEM 容量固定，<code>Bq</code> 与 <code>Bk</code> 的乘积受限于可用 SMEM，分块过小则 occupancy 与 MMA 吞吐同时受损。工程判断是让 <code>Bk</code> 取到 SMEM 允许的上限、<code>Bq</code> 适度缩小以维持多 CTA 并发，用流水线双缓冲掩盖加载延迟。</p>\n<p>具体例子：跨帧注意力在分块边界处的行为最敏感。当 <code>Bk</code> 恰好切在一帧的末尾，下一个 KV 块从下一帧起始地址开始，若两帧在显存中不连续（例如分帧存储的潜变量），加载会退化为两次独立事务。解决办法是在投影阶段就把多帧潜变量写成连续缓冲，使展平后的 <code>N</code> 维在物理上连续，分块加载退化为纯线性读。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-9\">九 · FP8 MMA 上的 QK^T 与在线 softmax 更新</h3>\n<p>瓦片进入计算阶段：<code>Q_i</code> 与 <code>K_j^T</code> 在 FP8 MMA 上相乘，得分 <code>s_ij = (Δ_q Δ_k / √d)·(Q̂_i K̂_j^T)</code> 以 FP32 累加器落盘。缩放因子 <code>Δ_q Δ_k</code> 在乘加后统一施加，避免在 FP8 域内做除法。随后进入在线 softmax：对当前块求块内最大值，与 running max 比较并更新，归一化因子按</p>\n<div class=\"formula\">$$m^{\\text{new}}=\\max(m,\\ \\max_j s_j),\\quad \\ell^{\\text{new}}=e^{m-m^{\\text{new}}}\\ell+\\sum_j e^{s_j-m^{\\text{new}}}$$</div>\n<p>递推。这一步的输入是 FP32 得分块与上一轮的 <code>m</code>、<code>ℓ</code>，输出是更新后的 <code>m</code>、<code>ℓ</code> 以及待量化的 P 块。代价是每块一次指数运算与一次归约，指数在 SFU 上执行，块越大摊薄越充分；但 <code>m</code> 的更新会触发对已累积输出 <code>O_i</code> 的重缩放，重缩放次数等于 KV 块数，是纯 FP32 的逐元素乘，在 <code>d=128</code> 时每块 <code>Bq×d</code> 次乘法，与 MMA 相比占比很小但不可省。</p>\n<p>数值上的关键点是 <code>m</code> 必须用 FP32 保存且跨块单调不减。若把 <code>m</code> 降精度，<code>e^{m-m^{\\text{new}}}</code> 在尖峰处会失真，导致归一化因子与真实分布偏离，表现为注意力权重整体偏移。具体例子：当某一帧出现高对比度边缘，该帧 token 的得分显著高于其余帧，块内最大值跳变，<code>m</code> 随之抬升，此前累积的 <code>ℓ</code> 被乘以一个很小的因子——这正是在线算法正确性的来源，也是它必须保持 FP32 的原因。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-10\">十 · P 量化到 E4M3 与 FP8 PV 乘</h3>\n<p>softmax 输出的概率块 <code>P</code> 在写回前被量化为 E4M3，再与 E4M3 的 V 块做 PV 乘，累加器保持 FP32。这一步的输入是 FP32 的归一化概率与 V 块，输出是 FP32 的部分输出 <code>O_i</code>。代价有两层：计算上 PV 与 QK 同为 <code>O(N²d)</code>，FP8 使两者吞吐相对 BF16 翻倍，这是内核收益的主要来源；数值上 P 的量化误差直接乘到 V 上，误差不经过 softmax 的平滑，而是按概率加权累积。</p>\n<p>失败模式集中在这里：softmax 尖峰处概率接近 1，相邻概率极小，E4M3 的 3 位尾数在 <code>[0.5, 1)</code> 区间的分辨率约为 <code>2^{-4}</code>，尖峰值的相对误差被放大后，权重分布出现塌缩——本该分散在若干帧上的注意力被压到单一 token，解码结果表现为细节丢失与纹理模糊。缓解手段是保留部分高精度通道：对每个头指定若干通道走 BF16 路径，或对尖峰超过阈值的块做混合精度回退，把该块的 P 以 BF16 参与 PV。代价是回退路径破坏 MMA 的整齐流水，触发频率高时吞吐下降，因此阈值要按头统计而非逐块动态判定。</p>\n<p>具体例子：在长视频的跨帧注意力中，首帧与当前帧的对应 token 得分往往形成尖峰，若整段序列统一走 FP8 PV，这些尖峰的量化误差会沿去噪步数累积。工程做法是把跨帧注意力单独标记，对这些头保留 BF16 的 P，而帧内注意力全量走 FP8——用头级精度分配换取稳定性和吞吐的折中。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-11\">十一 · 输出反缩放与写回 BF16</h3>\n<p>最后一个 KV 块处理完毕后，<code>O_i</code> 需除以归一化因子 <code>ℓ</code>，再乘以 Q 的行缩放因子之倒数，得到真实输出，写回 BF16 供后续 MLP 与残差连接使用。这一步的输入是 FP32 累加器、<code>ℓ</code> 与 <code>Δ_q</code>，输出是 BF16 的输出块。代价是每个 query 行一次除法与一次类型转换，属于 <code>O(Nd)</code> 量级，相对注意力主体可忽略，但它是精度链条的收口：若反缩放用低精度执行，前面 FP32 累加的努力会被抹掉。</p>\n<p>写回的布局必须与下游 MLP 的输入布局一致。视频 DiT 中注意力输出通常要经过输出投影再进 MLP，若内核写回的是头主序而投影期望序列主序，中间会插入一次转置，代价是额外的 HBM 往返。工程判断是把输出投影的权重布局一并按头主序重排，让反缩放后的写回直接连续，避免这次转置。这一步与显存带宽直接相关：<code>N·d</code> 个 BF16 元素的写回在长序列下是数十 MB 级流量，转置会让它翻倍。</p>\n<p>具体例子：当 <code>N</code> 达数万、<code>d=128</code>、头数 24 时，单次注意力的输出写回量在百 MB 量级，若叠加转置则等效带宽需求翻倍，在 HBM 带宽受限的配置下会成为新的瓶颈。把布局对齐做在权重准备阶段，是零运行时成本的解法。至此，一个请求的注意力路径从投影、切分、缩放、分块加载、FP8 MMA、在线 softmax、P 量化、PV 乘到反缩放写回走完，每一步的精度归属与访存形态都已固定，剩下的调优空间只在分块尺寸与 SMEM 占用上。</p>\n\n\n<h3 id=\"alg-fp8-attn-video-sec-12\">十二 · 分块流水线上的四道坎：FP8 时空注意力在 SM100 上的失效面</h3>\n\n<p>把这条数据流摊开看，每一步都有明确的输入输出与代价。QKV 投影后按头切分，输入是 BF16 潜变量，输出是逐头 Q/K/V；行级缩放取每行最大绝对值，把 E4M3 的动态范围压进 ±448，代价是一次额外的行归约与缩放因子存储——每头每行一个 FP32 scale，显存开销与 N 成正比，可忽略，但归约本身要在 MMA 之前串行完成，若与投影 kernel 未融合，就多出一次 HBM 往返。随后沿时间-空间展平序列分块流式加载 K/V：输入是展平后的 KV 块，输出是驻留 SMEM 的 E4M3 块，代价是 SMEM 占用与分块数的乘积决定 occupancy。这一步是整条链路最容易被误判的地方——展平顺序若按“先空间后时间”，相邻 token 在帧内连续，跨帧跳跃；若按“先时间后空间”，同一空间位置跨帧连续而帧内跳跃。视频注意力的相关性结构偏向后者，但 HBM 合并访问偏好前者，二者冲突时带宽利用率骤降，长视频分块边界处延迟明显上升。</p>\n\n<p>QK^T 在 FP8 MMA 上算出得分块，softmax 在线更新 running 状态，这是数值风险的集中点。分块内得分进入更新式：</p>\n\n<div class=\"formula\">$$m^{\\text{new}}=\\max(m,\\ \\max_j s_j),\\quad \\ell^{\\text{new}}=e^{m-m^{\\text{new}}}\\ell+\\sum_j e^{s_j-m^{\\text{new}}}$$</div>\n\n<p>问题在于 P 矩阵要被量化回 E4M3 才能与 V 做 FP8 PV 乘。softmax 输出天然落在 (0,1]，E4M3 在该区间的相对分辨率并不均匀，尖峰处概率接近 1 的少数 token 承担了绝大部分权重，量化误差被直接放大为注意力权重塌缩与细节丢失——表现为生成视频中运动边界模糊、纹理在高频区域退化。工程上的边界条件是：当序列内得分分布方差大（长视频跨帧注意力常见），尖峰越尖，E4M3 的 3 位尾数越不够用。缓解手段是保留部分高精度通道，即对权重最大的若干头或若干 token 走 BF16 回退路径，代价是这部分通道吞吐退回 BF16 水平，混合精度分支带来 warp 级分歧与额外寄存器压力。</p>\n\n<p>PV 乘的累加器保持 FP32，输出反缩放写回 BF16 供 MLP 与残差使用，这一步代价最低但最不能省：E4M3 的 PV 若用 FP16 累加，长序列累加误差随块数线性累积，反缩放后残差通路的数值一致性被破坏。真正的系统代价落在分块大小与 SMEM 占用的联合调优上。SM100 的 SMEM 容量固定，分块越大，单块 K/V 驻留越多、HBM 流量越小，但 occupancy 下降；分块越小，occupancy 上升而重复加载 K/V 的带宽开销上升。存在一个使 FP8 MMA 吞吐兑现的窗口：occupancy 过低时，MMA 流水填不满，FP8 相对 BF16 的吞吐优势无法兑现，内核甚至慢于 BF16 版本。判断依据不是单步延迟，而是“单步注意力时延 × 峰值显存”这一对 SLO 指标同时满足时的最大分块。适用边界因此清晰：分辨率与帧数较大、注意力占主导时延的视频扩散模型收益最大；序列极长时仍需配合长视频分块与重叠策略，把跨块边界的重算代价摊薄，否则分块边界处的延迟尖峰会把平均收益吃掉。</p>\n\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入 → 输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>行级缩放</td><td>BF16 Q/K → E4M3 + FP32 scale</td><td>行归约串行、一次 HBM 往返</td><td>未与投影融合</td></tr><tr><td>分块加载 K/V</td><td>展平序列 → SMEM 块</td><td>SMEM 占用决定 occupancy</td><td>展平顺序破坏合并访问</td></tr><tr><td>QK^T + 在线 softmax</td><td>E4M3 块 → FP32 running 状态</td><td>MMA 吞吐、寄存器压力</td><td>得分方差大、尖峰量化</td></tr><tr><td>P 量化 + PV</td><td>E4M3 P、V → FP32 累加</td><td>混合精度分支分歧</td><td>尖峰处权重塌缩</td></tr></tbody></table>\n<h3 id=\"alg-fp8-attn-video-sec-13\">十三 · 得分公式的逐项拆解：缩放因子为何放在FP8乘法之外</h3>\n<p>核心公式的第一行是加权求和，第二行才是本片段的重点：<span class=\"formula\">$$s_{ij}=\\frac{\\Delta_{q}\\Delta_{k}}{\\sqrt{d}}\\,(\\hat{Q}_{i}\\hat{K}_{j}^{\\top})$$</span>。这里 <span class=\"formula\">$$\\hat{Q},\\hat{K}$$</span> 是已经落到 E4M3 网格上的张量，<span class=\"formula\">$$\\Delta_{q},\\Delta_{k}$$</span> 是各自的行级反缩放系数（Q 按行最大值、K 按行最大值折算到 E4M3 的动态范围），<span class=\"formula\">$$d$$</span> 是头维。关键一步在于：<span class=\"formula\">$$\\Delta_{q}\\Delta_{k}/\\sqrt{d}$$</span> 这一串标量必须在 FP8 MMA 之外、以 FP32 施加到累加结果上，而不能预先折进 <span class=\"formula\">$$\\hat{Q}$$</span> 或 <span class=\"formula\">$$\\hat{K}$$</span> 的存储值里。原因很直接——E4M3 只有 4 位指数、3 位尾数，把 <span class=\"formula\">$$1/\\sqrt{d}$$</span> 乘进量化张量会额外吃掉指数位，把原本落在可表示区间内的行推向下溢或上溢边缘；而留在外面，MMA 看到的是两个“归一化到同一量级”的纯尾数矩阵，乘积的动态范围被压缩在可控区间内。</p>\n<p>推导上的第二步是误差项：<span class=\"formula\">$$\\text{err}\\propto 2^{-4}\\lVert Q\\rVert\\lVert K\\rVert$$</span>。系数 <span class=\"formula\">$$2^{-4}$$</span> 来自 E4M3 的 3 位尾数（相对精度约 <span class=\"formula\">$$2^{-4}$$</span>），而 <span class=\"formula\">$$\\lVert Q\\rVert\\lVert K\\rVert$$</span> 说明绝对误差随两个张量的范数线性放大——这解释了为什么必须做行级缩放：不缩放时某一行范数偏大，该行所有得分一起带上大误差，softmax 之后整行权重被污染；按行缩放后每行范数被拉到 1 附近，误差项对行与行之间近似均匀。工程代价体现在这里：行最大值归约要在 QKV 投影输出后立刻做一次，对每个头、每一行扫一遍，属于纯带宽操作，在 B200 上这段归约的耗时与后续 MMA 相比不可忽略，但它是把误差从“行间失衡”压成“行内均匀”的唯一手段。</p>\n<p>具体例子：一个 720p、若干帧的视频潜变量展平后序列长度达到万级，头维 128，若不缩放直接量化，某些帧的 K 行因跨帧内容差异范数偏大，得分整体上移，softmax 尖峰被推到 E4M3 无法细分的区间；加上行级缩放后，同一批次内各帧的得分分布被拉回同一量级，尖峰处的权重才落回可表示范围。这一步不产生任何吞吐收益，却是后面所有 FP8 收益成立的前提。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-14\">十四 · 在线 softmax 的 running 更新：分块之间的状态只有三个标量</h3>\n<p>公式第二组是分块流式 softmax 的状态递推：<span class=\"formula\">$$m^{\\text{new}}=\\max(m,\\ \\max_j s_j),\\quad \\ell^{\\text{new}}=e^{m-m^{\\text{new}}}\\ell+\\sum_j e^{s_j-m^{\\text{new}}}$$</span>。这里 <span class=\"formula\">$$s_j$$</span> 是当前 K/V 块内算出的得分向量，<span class=\"formula\">$$m$$</span> 是此前所有块见过的最大值，<span class=\"formula\">$$\\ell$$</span> 是此前所有块的归一化因子累加。递推的推导关键一步是“重标定”：当新块带来更大的 <span class=\"formula\">$$m^{\\text{new}}$$</span> 时，旧的 <span class=\"formula\">$$\\ell$$</span> 必须乘上 <span class=\"formula\">$$e^{m-m^{\\text{new}}}$$</span> 才能与新块的指数项对齐到同一基准，否则两块的和会混用不同基准、结果无意义。同理，已经累加进输出累加器的 <span class=\"formula\">$$O$$</span> 也要按同一因子重标定——这是实现里最容易漏掉的一步，漏掉它不会报错，只会让长序列尾部的输出悄悄偏移。</p>\n<p>这套递推把跨块状态压缩到三个量：<span class=\"formula\">$$m$$</span>、<span class=\"formula\">$$\\ell$$</span>、以及 FP32 的输出累加器（形状为头维）。代价是每处理一个新块，都要对累加器做一次逐元素乘 <span class=\"formula\">$$e^{m-m^{\\text{new}}}$$</span>；当 <span class=\"formula\">$$m$$</span> 不变时该因子为 1，可以跳过，实际实现里通常用一个分支判断 <span class=\"formula\">$$m^{\\text{new}}&gt;m$$</span> 来决定是否重标定，避免无谓的乘加。在 SM100 上，这个分支的代价是 warp 内的分歧与少量寄存器搬运，相对于一次 tcgen05 MMA 可以忽略，但块划得太小（例如每块只装几十个 K 行）时，重标定次数随块数线性上升，会成为固定开销。</p>\n<p>具体例子：把时间-空间展平序列切成若干 K/V 块，前几块来自同一帧，得分分布窄，<span class=\"formula\">$$m$$</span> 缓慢爬升；跨到下一帧时若内容突变，新块的最大得分明显抬高，触发一次重标定，累加器整体缩放。若展平顺序把不同帧交错排列，这种触发会频繁发生，重标定开销与访存不合并叠加，正是失败模式里“跨帧展平顺序不当”在数值层面的表现。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-15\">十五 · P 的量化与 PV 乘：为什么累加器必须是 FP32</h3>\n<p>softmax 归一化后的权重矩阵 <span class=\"formula\">$$P$$</span> 要再量化成 E4M3 才能进第二次 FP8 MMA。这一步的推导要点是：<span class=\"formula\">$$P$$</span> 的元素落在 <span class=\"formula\">$$[0,1]$$</span> 且行和为 1，本身动态范围不大，但分布极不均匀——softmax 尖峰处少数元素接近 1，其余接近 0。E4M3 在接近 1 的一侧尾数最密，在接近 0 的一侧则迅速失去分辨力，因此尖峰元素的相对误差小、尾部元素的相对误差大。由于 PV 乘是对 <span class=\"formula\">$$V$$</span> 的加权平均，尾部元素误差被其小权重压制，真正危险的是尖峰元素被量化后权重塌缩——一旦最大权重从接近 1 掉到次一档网格，注意力就从“聚焦”变成“弥散”，细节丢失。</p>\n<p>累加器保持 FP32 的理由与此互补：<span class=\"formula\">$$P$$</span> 与 <span class=\"formula\">$$V$$</span> 都是 FP8，单次乘积的尾数位有限，但沿序列方向累加的次数是万级，若用 FP16 累加，舍入误差随累加步数累积，长序列尾部的输出会出现可见漂移；FP32 累加把每次乘积的舍入误差压在累加器精度之下，使误差不随序列长度增长。代价是累加器占用的寄存器与 TMEM 容量翻倍——在 SM100 上，输出累加器按头维驻留，FP32 意味着每个输出元素 4 字节，头维 128、每 SM 同时驻留多个块时，这部分占用直接决定 occupancy 上限，也是“分块大小受 SMEM 容量限制”的具体来源之一。</p>\n<p>具体例子：一个尖峰权重 <span class=\"formula\">$$p\\approx0.98$$</span> 量化为 E4M3 后落到相邻网格，误差在千分位量级；单看一次 PV 乘无感，但它乘上的 <span class=\"formula\">$$V$$</span> 行若恰好承载该帧的关键纹理，输出在该通道上的偏差会沿残差与后续 MLP 放大。工程上的对策不是提高整块精度，而是保留少量高精度通道：对尖峰所在的行或通道做 BF16 回退，其余走 FP8，用混合精度把误差摁在尖峰处而不牺牲整体吞吐。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-16\">十六 · 伪代码：把公式落到 SM100 的块循环上</h3>\n<p>下面给出可实现的内核骨架，只保留与本片段公式对应的控制流与状态：</p>\n<p>对每个 (头, 查询块)：从 FP32 投影结果取 <span class=\"formula\">$$Q$$</span> 块，按行最大值求 <span class=\"formula\">$$\\Delta_{q}$$</span>，量化为 E4M3 写入 SMEM；初始化 <span class=\"formula\">$$m=-\\infty,\\ \\ell=0$$</span>，FP32 累加器 <span class=\"formula\">$$O=0$$</span>；沿展平序列循环取 <span class=\"formula\">$$K,V$$</span> 块（同样行缩放后量化），在 tcgen05 上算 <span class=\"formula\">$$\\hat{Q}\\hat{K}^{\\top}$$</span> 得 FP32 得分，乘 <span class=\"formula\">$$\\Delta_{q}\\Delta_{k}/\\sqrt{d}$$</span> 得 <span class=\"formula\">$$s$$</span>；按第二节递推更新 <span class=\"formula\">$$m,\\ell$$</span> 并在 <span class=\"formula\">$$m$$</span> 变化时重标定 <span class=\"formula\">$$O$$</span>；把 <span class=\"formula\">$$e^{s-m^{\\text{new}}}$$</span> 量化为 E4M3 得 <span class=\"formula\">$$P$$</span>，与 <span class=\"formula\">$$V$$</span> 做 FP8 MMA 累加进 FP32 <span class=\"formula\">$$O$$</span>；循环结束后 <span class=\"formula\">$$O/\\ell$$</span> 反缩放，写回 BF16。</p>\n<p>伪代码里两个易错点值得单列。其一，<span class=\"formula\">$$\\Delta_{q}$$</span> 的施加位置：必须在得分累加完成后乘，若提前折进 <span class=\"formula\">$$\\hat{Q}$$</span> 会破坏第一节讲的动态范围；<span class=\"formula\">$$\\Delta_{k}$$</span> 同理，但 K 块是流式加载的，其行缩放系数要随块一起搬进 SMEM，不能事后补。其二，<span class=\"formula\">$$P$$</span> 的量化必须用 <span class=\"formula\">$$m^{\\text{new}}$$</span> 而不是旧 <span class=\"formula\">$$m$$</span>，否则指数项基准错位，量化后的 <span class=\"formula\">$$P$$</span> 整体偏大或偏小，PV 结果与 <span class=\"formula\">$$\\ell$$</span> 不自洽。</p>\n<p>代价核算：块循环的每一次迭代包含一次 QK MMA、一次重标定分支、一次 P 量化写回 SMEM、一次 PV MMA。FP8 使两次 MMA 的吞吐相对 BF16 翻倍，但 P 量化与重标定是纯标量/向量操作，不随 MMA 加速——块越大，这部分固定开销被摊得越薄；块越小，occupancy 越高但开销占比上升。SM100 上调参的实际动作就是在 SMEM 容量、TMEM 占用与块大小之间找这个平衡点，调不好时 FP8 MMA 的吞吐优势兑现不了，内核甚至慢于 BF16 版本。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-17\">十七 · 展平顺序与访存合并：公式之外的第四个约束</h3>\n<p>公式只描述数值，不描述数据怎么从 HBM 进来。时空注意力的序列是时间与空间两个维度展平得到的，展平顺序决定了相邻 K/V 行在 HBM 上是否连续。若按“帧内空间优先、帧间次之”展平，同一 K/V 块内的行大多来自同一帧、地址连续，块加载能形成宽事务、带宽利用率高；若把帧交错进同一块，块内行跨帧跳跃，每次加载退化成多个窄事务，带宽利用率骤降——这正是失败模式里“跨帧展平顺序不当”的机制。它对本片段的意义在于：第一节的行级缩放、第二节的重标定频率、第三节的尖峰分布，全都受展平顺序间接影响，因为顺序决定了块内得分的统计特性。</p>\n<p>工程判断落在两处。其一，展平顺序应在进入内核前就固定，作为张量布局的一部分传给内核，而不是在内核里临时重排——临时重排意味着额外的 SMEM 往返，代价与一次重标定同量级但收益不确定。其二，块大小要与展平后的地址连续性匹配：块跨越帧边界时，块内地址连续性被打断，此时应缩小块或在该边界处插入对齐，宁可多一次重标定也不让带宽掉下去。在 B200 上，这两条约束与 SMEM 容量共同决定了可用的块大小区间，区间外的配置要么 occupancy 不足，要么带宽利用率不足，二者都会让 FP8 的吞吐翻倍变成纸面数字。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-18\">十八 · 失效边界：P 量化尖峰、展平顺序与 SMEM 占用的三重约束</h3>\n<p>FP8 时空注意力内核的收益并非无条件成立，它的失效条件集中在三处：P 矩阵的量化误差、跨帧展平顺序、以及分块与 SMEM 的匹配度。先看数值侧。核心公式中 <span class=\"formula\">$$O_{i}=\\frac{\\sum_{j}e^{s_{ij}-m_{i}}\\,V_{j}}{\\sum_{j}e^{s_{ij}-m_{i}}},\\quad s_{ij}=\\frac{\\Delta_{q}\\Delta_{k}}{\\sqrt{d}}\\,(\\hat{Q}_{i}\\hat{K}_{j}^{\\top}),\\quad \\text{err}\\propto 2^{-4}\\lVert Q\\rVert\\lVert K\\rVert$$</span> 的误差项只约束了 QK^T 一侧，真正的风险在 P 被量化为 E4M3 之后。softmax 尖峰意味着某一列权重接近 1、其余接近 0，E4M3 的尾数位宽在接近 1 的区域分辨率有限，尖峰邻域的权重被压平，表现为注意力权重塌缩与细节丢失。工程判断是：对尖峰敏感的头保留 BF16 或 FP16 的 PV 路径，或对 P 做分块级缩放后再量化，代价是这部分头失去 FP8 PV 的吞吐翻倍，混合精度回退会让整体注意力时延落在 BF16 与全 FP8 之间。</p>\n<p>访存侧约束同样硬。时空注意力把序列沿时间-空间展平，展平顺序决定 K/V 分块加载时 HBM 访问是否连续。若按帧内空间优先、帧间跳跃的次序展平，同一分块内的 K/V 行在显存中不连续，合并访问被破坏，带宽利用率骤降，长视频分块边界处的延迟明显上升——这正是分块边界延迟不降反升的典型来源。可实现的伪代码思路是：展平索引按 <em>frame-major、patch-minor</em> 生成，使相邻 token 在时间维上连续；分块循环内先算 running 更新 <span class=\"formula\">$$m^{\\text{new}}=\\max(m,\\ \\max_j s_j),\\quad \\ell^{\\text{new}}=e^{m-m^{\\text{new}}}\\ell+\\sum_j e^{s_j-m^{\\text{new}}}$$</span> 再做 P 量化与 FP8 PV 乘，累加器保持 FP32，输出反缩放写回 BF16。</p>\n<p>第三重约束是分块大小与 SMEM 占用。SM100 上 FP8 MMA 的吞吐优势要靠足够 occupancy 兑现；分块过大挤占 SMEM，活跃 warp 组减少，MMA 流水填不满，内核可能慢于 BF16 版本。分块过小则 K/V 重加载次数上升，带宽开销吃掉算力收益。调优目标是让 Q 块、K/V 块与 P 缓冲的 SMEM 占用落在能维持多块并发的区间，同时让 FP8 PV 的 FP32 累加器不溢出寄存器预算。系统代价可定性表述为：显存从 O(N^2) 降到 O(N) 是确定的，但峰值显存仍受分块与并发块数影响；吞吐翻倍只在 occupancy 达标时成立。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测现象</th><th>工程对策</th></tr></thead><tbody><tr><td>P 量化为 E4M3 于 softmax 尖峰</td><td>权重塌缩、细节丢失</td><td>敏感头保留高精度通道或混合精度回退</td></tr><tr><td>跨帧展平顺序不当</td><td>HBM 合并访问破坏、带宽利用率骤降</td><td>frame-major 展平，分块边界对齐</td></tr><tr><td>分块与 SMEM 未针对 SM100 调优</td><td>occupancy 过低、慢于 BF16 内核</td><td>按 SMEM 预算反推块尺寸与并发块数</td></tr></tbody></table>\n<p>适用边界因此可判定：该内核适合分辨率与帧数较大、注意力占主导时延的视频扩散前向；序列极长时仍需配合长视频分块与重叠策略，且跨帧展平顺序必须与分块加载协同设计，否则 O(N) 显存优势会被带宽损失抵消。</p>\n<h3 id=\"alg-fp8-attn-video-sec-19\">十九 · 请求形态：什么样的前向才吃得到 FP8 的红利</h3>\n<p>这套内核的收益不是均匀分布的，它只在“注意力占主导时延”的请求形态上兑现。判据很直接：把一次去噪步的时延拆成 QKV 投影、时空注意力、MLP、VAE 解码几段，注意力占比越高，FP8 替换 BF16 的端到端收益越大。分辨率与帧数同时抬升时，序列长度沿时间-空间展平后近似平方增长，QK^T 与 PV 的 FLOPs 与中间激活同步膨胀，此时 BF16 注意力的 O(N²) 显存与 MMA 时延会压过其余算子，FP8 路径的吞吐翻倍才有意义。</p>\n<p>反过来，短序列、低分辨率、少帧的请求是这套内核的坏负载。序列短到分块循环只跑一两轮时，行级缩放的预处理开销、running max 与归一化因子的在线更新、输出反缩放写回 BF16 这些固定成本摊不掉，FP8 MMA 相对 BF16 的理论吞吐优势被这些标量路径吃掉。工程上的判断是：先用 BF16 内核跑一遍 profile，若注意力段占单步时延不足主导份额，就不要切 FP8，切了也是负收益。</p>\n<p>请求形态还决定展平顺序。时空注意力把 (T, H, W) 展平成一维序列，跨帧注意力的展平顺序必须让同一分块内加载的 K/V 在 HBM 上连续，否则分块流式加载退化为跨步访问，带宽利用率骤降。这一点在负载配方里不是可选项：请求的视频帧数与分辨率组合一旦变化，展平顺序与分块边界的对齐关系就变，需要按负载档位预先固定展平策略，而不是在运行时按请求临时推导。</p>\n<div class=\"formula\">$$N = T \\cdot H \\cdot W,\\qquad \\text{attn\\_share} = \\frac{\\text{latency}_{\\text{QK}} + \\text{latency}_{\\text{PV}}}{\\text{latency}_{\\text{step}}}$$</div>\n<p>具体例子：一段高分辨率长视频的潜变量展平后序列长度达到数万量级，注意力段在单步时延中占主导，此时 FP8 内核把 QK 与 PV 放到 FP8 MMA 上执行、累加器保持 FP32，吞吐翻倍直接转化为单步时延下降；而同一模型在低分辨率短片段上，序列长度只有前者的零头，注意力段占比低，切换 FP8 后单步时延几乎不动，反而多出量化与反缩放的分支。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-20\">二十 · 长度分布：批内序列长度方差决定分块调度</h3>\n<p>连续批处理下，一个 batch 里塞进的请求序列长度并不一致。FP8 时空注意力内核按 FlashAttention 式分块沿序列流式加载 K/V，分块大小与 SMEM 占用绑定，因此批内最长序列决定了分块循环的轮数，而最短序列的请求被迫陪跑。长度方差越大，SM 上实际有效的 FP8 MMA 利用率越低：短请求的分块循环早早结束，长请求还在跑，尾部效应把批级吞吐拉下来。</p>\n<p>负载配方的做法是按长度分桶而非按到达顺序拼批。把序列长度接近的请求放进同一批，使批内分块轮数一致，occupancy 稳定，FP8 MMA 的吞吐优势才能持续兑现。长度分桶的代价是排队时延：为了凑齐同桶请求，调度器要等待，SLO 以单步注意力时延与峰值显存衡量时，这段等待必须计入容量规划。桶宽的选择是吞吐与尾延迟的折中，桶越窄批内越齐、吞吐越高，但等待越久。</p>\n<p>长度分布还影响显存。注意力显存从 O(N²) 降到 O(N) 是靠分块流式加载实现的，但每个请求仍需驻留自己的 K/V 块缓冲与 FP32 累加器。批内长序列请求越多，峰值显存越高；若按最长序列预留 SMEM 与寄存器，短请求的槽位被浪费，occupancy 被拉低。工程上按桶配置分块大小，让 SMEM 占用匹配该桶的典型序列长度，而不是全局取最长。</p>\n<table class=\"mini\"><thead><tr><th>长度分布形态</th><th>分块调度后果</th><th>系统代价</th></tr></thead><tbody><tr><td>批内长度接近</td><td>分块轮数一致，occupancy 稳定</td><td>FP8 MMA 吞吐兑现，批级吞吐高</td></tr><tr><td>批内长短混杂</td><td>短请求陪跑长请求的尾部</td><td>SM 有效利用率下降，尾延迟抬升</td></tr><tr><td>极长序列单请求</td><td>分块轮数极多，SMEM 占用顶格</td><td>峰值显存高，需配合长视频分块与重叠</td></tr></tbody></table>\n<p>具体例子：同一批里混入一条数万 token 的长视频请求与若干短片段请求，短请求的分块循环几轮就结束，长请求把整批的完成时间拖到它的尾部；若改为按长度分桶，短桶与长桶各自成批，短桶的批级吞吐显著高于混批，长桶则单独按 SMEM 顶格配置分块大小。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-21\">二十一 · 并发与批大小：头数、分块与 SM 占用三者互相牵制</h3>\n<p>批大小不是越大越好。FP8 时空注意力内核按头切分 Q/K/V，每个头独立做分块在线 softmax，批大小乘以头数决定同时活跃的注意力实例数。实例数超过 SM 能承载的并发块数时，多出来的实例排队等 SMEM 与寄存器，occupancy 反而下降。SM100 上分块大小与 SMEM 占用需专门调优，调优的目标是让每个 SM 上同时驻留的分块数与 FP8 MMA 的流水深度匹配，而不是把批塞满。</p>\n<p>并发的另一个约束是 PV 累加器。PV 乘在 FP8 MMA 上执行但累加保持 FP32，每个活跃分块都要占一份 FP32 累加器寄存器。批大小翻倍，累加器占用翻倍，寄存器压力上升会压低 occupancy，使 FP8 MMA 的吞吐优势无法兑现，极端情况下慢于 BF16 内核。这就是失败模式里“分块大小与 SMEM 占用未针对 SM100 调优时 occupancy 过低”的具体来源。</p>\n<div class=\"formula\">$$\\text{occupancy} \\approx \\frac{\\text{SMEM}_{\\text{per SM}}}{\\text{SMEM}_{\\text{block}} \\cdot n_{\\text{block}}},\\qquad n_{\\text{block}} \\propto B \\cdot H$$</div>\n<p>负载配方的做法是把批大小按头数与序列分块配置：给定头数 H 与目标分块大小，先算出单实例的 SMEM 与寄存器占用，再反推每个 SM 能驻留的实例数，最后得到批大小上限。这个上限不是固定值，它随序列长度桶变化——长序列桶的分块更大、SMEM 占用更高，批大小上限更低；短序列桶反之。容量规划时按桶分别给出批大小上限，而不是全局一个数。</p>\n<p>具体例子：某长视频桶下单实例分块占满 SMEM 的可观份额，批大小设到 2 时 occupancy 已接近上限，再往上加批只会让实例排队；而同一模型在短序列桶下分块小、SMEM 占用低，批大小可以放到更高，吞吐随批线性上升直到寄存器成为瓶颈。两个桶的批大小上限相差数倍，混用同一个批大小配置必然在其中一个桶上浪费资源。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-22\">二十二 · 负载不对时的第一类崩塌：P 量化误差在尖峰处放大</h3>\n<p>负载与内核不匹配时，最先暴露的往往不是性能而是数值。P 矩阵量化为 E4M3 后，softmax 尖峰处的量化误差被放大：注意力权重集中在少数 token 上时，尖峰附近的概率值对量化步长极其敏感，E4M3 的尾数位不足以分辨相邻概率，表现为注意力权重塌缩与细节丢失。序列越长、注意力越尖锐，这个问题越突出，因为长序列的 softmax 分布天然更集中。</p>\n<p>误差的量级由公式给出：err ∝ 2⁻⁴‖Q‖‖K‖，4 位尾数决定了相对误差的下界，而行级缩放只能抑制溢出、不能提升尾数分辨率。当负载是长视频、跨帧注意力权重高度集中时，尖峰处的相对误差被 softmax 的指数放大，输出细节丢失在后续 MLP 与残差里被进一步传播。这不是可以通过调分块大小解决的性能问题，而是精度配方问题。</p>\n<p>工程上的应对是保留部分高精度通道或做混合精度回退：对注意力尖峰敏感的少数头或少数通道保留 BF16 路径，其余走 FP8；或者在检测到权重集中度超过阈值时对该分块回退到 BF16 计算。代价是吞吐：混合精度回退让部分分块退回 BF16 MMA，整体吞吐低于纯 FP8，但仍高于全 BF16。负载配方里要把这条回退路径的触发条件写进 SLO——当请求形态偏向长视频高分辨率时，预留回退预算。</p>\n<p>具体例子：一段跨帧注意力权重集中在少数关键帧上的长视频，纯 FP8 路径下尖峰处的权重被量化压平，解码结果出现细节模糊；开启按头的高精度通道保留后，尖峰头走 BF16、其余头走 FP8，细节恢复而吞吐只下降有限份额。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-23\">二十三 · 负载不对时的第二类崩塌：展平顺序破坏访存合并</h3>\n<p>第二类崩塌是纯性能的。跨帧注意力展平顺序不当会破坏 HBM 访存合并，分块加载 K/V 时带宽利用率骤降，长视频分块边界处延迟明显上升。时空注意力的展平把 (T, H, W) 压成一维，若展平让同一分块内的 K/V 在 HBM 上跨大步分布，每次分块加载都退化为大量离散小事务，HBM 的有效带宽远低于峰值，FP8 MMA 再快也喂不饱。</p>\n<p>这个问题的隐蔽之处在于它不报错、不掉精度，只是慢。负载配方必须把展平顺序与分块边界的对齐作为请求形态的一部分：帧数、分辨率变化时，展平后的空间邻接关系变化，原先对齐的分块边界可能失配。工程做法是按负载档位固定展平策略，并在分块边界处做对齐填充，使每个分块加载的 K/V 段落在 HBM 上连续。代价是填充带来的少量冗余计算与显存，换来的是带宽利用率回到可用区间。</p>\n<p>分块边界处的延迟上升还有第二层来源：在线 softmax 的 running max 与归一化因子在跨分块时更新，边界越多，标量更新路径的占比越高。长视频序列极长时，分块数多，边界开销累积。这也是为什么序列极长时仍需配合长视频分块与重叠策略——不是内核本身不够快，而是分块边界的管理成本随序列长度线性增长。</p>\n<p>具体例子：同一段长视频，展平顺序按帧优先时，同一分块内的 K/V 在 HBM 上连续，分块加载带宽利用率高；改为按空间优先展平后，分块内元素跨帧跳跃，加载事务离散化，带宽利用率骤降，长视频分块边界处的单步时延明显抬升，而计算量并未变化。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-24\">二十四 · 负载配方的工程判断：先定形态，再定批，最后定回退</h3>\n<p>把上面几条收拢成可执行的配方顺序。第一步定请求形态：用 BF16 内核 profile 单步时延分解，确认注意力段占主导才进入 FP8 路径；同时固定该形态下的展平顺序与分块边界对齐规则，把它作为负载档位的一部分固化下来。第二步定长度分桶与批大小：按序列长度分桶，每桶独立计算 SMEM 与寄存器占用，反推批大小上限，桶宽在吞吐与排队时延之间取折中。第三步定回退预算：按桶评估注意力权重集中度，为长视频高分辨率桶预留高精度通道或混合精度回退的吞吐预算，写进 SLO 的容量规划。</p>\n<p>这套顺序的工程含义是：FP8 时空注意力内核的收益是条件收益，条件由请求形态、长度分布、并发批大小三者共同定义。三者任一失配，收益要么被数值崩塌吃掉，要么被 occupancy 与带宽崩塌吃掉。容量规划不能只按峰值吞吐算，而要按桶算——每个桶有自己的批大小上限、自己的回退预算、自己的展平策略。SLO 以单步注意力时延与峰值显存衡量时，这两个指标都必须按桶给出，而不是全局一个数。</p>\n<p>最后一个判断落在分块大小上。分块大小是这套内核唯一同时牵动 SMEM 占用、occupancy、访存合并与边界开销的旋钮，针对 SM100 调优它不是一次性动作，而是随负载桶变化的配置项。把分块大小当作按桶配置的参数而非全局常量，是这套内核在真实服务里稳住吞吐与延迟的分界线。</p>\n<h3 id=\"alg-fp8-attn-video-sec-25\">二十五 · 硬件档位：从单卡 SM100 到 NVL72 机柜的注意力落位</h3>\n<p>FP8 时空注意力内核的部署起点不是“有没有 Blackwell”，而是“注意力块落在哪一级硬件域”。单卡 B200/B300 上，一个注意力头的分块流式循环完全在片内完成：QKV 投影后的张量驻留 HBM，K/V 块经 TMA 搬入 SMEM，QK^T 与 PV 走 tcgen05 的 FP8 MMA 通路，累加器落在 TMEM 的 FP32 区。这一档位的约束是 SMEM 容量与 TMEM 配额——分块大小、每 CTA 承载的头数、是否启用 2-SM MMA（两个 SM 协同一个更大 MMA 形状）三者互相挤压。GB200/GB300 NVL72 档位则把问题变成拓扑问题：当序列沿时间-空间展平后超出单卡可承受的 KV 驻留量，注意力需要按头或按序列切分到多个 GPU，跨卡归约走 NVLink 5，此时 FP8 的价值不只是吞吐翻倍，更是把跨卡传输的字节数减半——KV 块以 E4M3 传输，接收端直接进 MMA，省掉一次反量化往返。</p>\n<p>档位选择的判据可以写成一个粗略的容量不等式：设单卡可用于 KV 块的 HBM 预算为 <span>M</span>，序列长度 <span>N</span>、头数 <span>H</span>、头维 <span>d</span>，则单卡可承载的 KV 元素上限约为 <span>M / (2 bytes)</span>（E4M3 每元素 1 字节，K 与 V 各一份）。当 <span>N·H·d·2</span> 超过该上限，就必须进入并行拓扑设计，而不是继续调分块大小。这里的工程判断是：先算清 KV 驻留需求，再决定是单卡多 CTA 切分、还是跨卡头并行。</p>\n<p>具体例子：一条 1080p、数十帧的潜变量序列，展平后 N 达到数万量级，单头 d=128、数十头的情形下 KV 字节数已逼近单卡预算边缘；此时把注意力按头切成两组放到两颗 GPU 上，每颗只持有自己那组头的 K/V，QK^T 与 PV 完全本地，仅输出在末尾做一次 all-gather 回 BF16 写回——跨卡通信量正比于输出而非 KV，这是 FP8 注意力在 NVL72 上最省带宽的切法。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-26\">二十六 · 并行拓扑：头并行优先，序列并行兜底</h3>\n<p>注意力路径的并行拓扑有三条可选路线，代价结构完全不同。头并行（head parallel）把不同注意力头分到不同 GPU，每卡独立完成自己头的完整在线 softmax 循环，无跨卡归约，通信只发生在输出拼接处，代价是每卡仍需持有完整序列的 K/V 分片——显存随头数线性下降，但随 N 线性上升。序列并行（sequence parallel）把展平后的序列切块分卡，每卡持有部分 K/V，QK^T 需要跨卡收集得分或做环形归约，通信量正比于 <span>N²</span> 的得分矩阵分片，代价高但对超长序列是唯一出路。第三种是 2-SM MMA 的片内拓扑：两个 SM 共享一个 MMA 指令的更大形状，等效于把一次分块矩阵乘的并行度翻倍，不涉及跨卡通信，但要求分块形状与 SMEM 布局严格对齐 SM100 的 tcgen05 约束。</p>\n<div class=\"formula\">$$\\text{comm}^{\\text{head}}=\\mathcal{O}(N d),\\quad \\text{comm}^{\\text{seq}}=\\mathcal{O}(N^{2}/P)\\ \\text{(score shards)}$$</div>\n<p>上式的含义直接决定选型：头并行的通信量与 N 线性相关且只传输出，序列并行的通信量随得分矩阵增长。因此在 KV 能放下时一律优先头并行；只有当单头 KV 分片仍超预算，才退到序列并行，并且此时应把 FP8 的得分分片直接以 E4M3 跨卡传输，避免 BF16 归约把带宽吃回去。</p>\n<p>具体例子：NVL72 内 8 卡一组，32 个注意力头按 4 头/卡切分，每卡 KV 预算降至 1/8，序列完整保留，跨卡只在输出端做一次拼接；若序列再涨一倍导致单卡 KV 仍不够，则改为 2 卡头并行 × 4 卡序列切块的混合拓扑，得分分片走 NVLink 5 环形归约，归约后的 running max 与归一化因子在各卡间同步更新，保证在线 softmax 的分块边界一致。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-27\">二十七 · 量化方案：E4M3 为主干，尖峰通道留高精度</h3>\n<p>量化方案不是“全上 FP8”一句话，而是分层决策。Q/K 按行最大值缩放至 E4M3，缩放因子随块存储，反缩放只在输出端做一次；V 同样 E4M3 存储，参与 PV 乘时与量化后的 P 在 FP8 MMA 上相乘，累加器保持 FP32——这一条是数值稳定的底线，不能省。P 的量化是风险点：softmax 尖峰处单个权重量级远高于其余元素，E4M3 的 4 位尾数在尖峰附近相对误差被放大，表现为注意力权重塌缩。工程上的对策是保留高精度通道：对每个头统计得分分布的尖峰比例，超过阈值的头（或头内的特定通道）在 P 量化时回退到 BF16 参与 PV 乘，其余走 FP8。回退比例直接换算成吞吐代价——回退通道占比 <span>r</span> 时，PV 的有效吞吐约为 <span>2/(1+r)</span> 倍 BF16 的水平，r 越小越接近翻倍。</p>\n<div class=\"formula\">$$\\text{err}\\propto 2^{-4}\\lVert Q\\rVert\\lVert K\\rVert,\\quad \\text{throughput}_{\\text{PV}}\\approx \\frac{2}{1+r}$$</div>\n<p>另一条量化决策是缩放粒度：行级缩放（per-row）实现简单、寄存器开销小，但对行内动态范围大的头不够；分块缩放（per-block，如 128 元素一块）能把尖峰局部化，代价是缩放因子存储与反缩放指令增加。SM100 上分块缩放的元数据可以随 K/V 块一起经 TMA 搬入，额外带宽开销可控，因此对尖峰明显的视频注意力，分块缩放加选择性回退是比纯行级更稳的组合。</p>\n<p>具体例子：某层注意力在跨帧边界处得分尖峰集中，行级缩放后 P 的 E4M3 量化使边界帧权重被压平，重建画面出现帧间拖影；改为 128 元素分块缩放并对该层 1/8 通道回退 BF16 后，尖峰保留，PV 吞吐仍维持在接近翻倍的水平——这就是“量化方案按层、按头、按通道分级”的实际收益。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-28\">二十八 · KV 策略：分块驻留与展平顺序绑定</h3>\n<p>FP8 注意力的 KV 策略核心不是缓存多少，而是“按什么顺序流式加载”。时间-空间展平顺序决定了 K/V 块在 HBM 上的连续性：若把帧维放在最内层，同一分块内的 K 元素跨越大量不连续地址，TMA 描述符需要更多维度跳转，HBM 访存合并被破坏，带宽利用率骤降；正确做法是把空间维（或空间内的连续 token 段）放在最内层，使一个分块对应一段连续 HBM 区间，TMA 一次搬运即满足合并要求。这一约束与通用 FlashAttention 不同，是本算法特有的部署前提。</p>\n<p>KV 驻留策略分两级：片内 SMEM 只保留当前流式窗口的 K/V 块，滚动覆盖；HBM 上保留完整序列的 E4M3 K/V，供跨分块重用。当序列极长、HBM 也放不下时，进入长视频分块与重叠策略的范畴（该策略另有专述，此处只指出注意力内核需暴露“按帧窗口加载”的接口，使外层分块器能把重叠帧的 K/V 预取进来）。驻留代价可以量化：SMEM 窗口大小 <span>B_k</span> 决定单次 MMA 的 K 维长度，<span>B_k</span> 越大，QK^T 的算术强度越高但 SMEM 占用越大、occupancy 越低；SM100 上需要在 occupancy 与单块效率之间取平衡点。</p>\n<p>具体例子：把 16 帧 × 空间 64×64 的展平序列按“帧外、空间内”排列，每块 256 个连续 token 作为一个 K/V 块，TMA 三维描述符只需在帧维跳转，空间维连续，带宽利用率恢复到接近峰值的水平；若误按“空间外、帧内”排列，同一块内地址跳转数十次，长视频分块边界处延迟明显上升——这是部署时最容易踩的坑，且不体现在任何单算子 benchmark 里。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-29\">二十九 · 调度参数：批、分块、occupancy 的三角约束</h3>\n<p>调度参数在注意力内核层面体现为三个互相牵制的量：批大小（同时处理的注意力头数或请求数）、分块大小（<span>B_q</span> 与 <span>B_k</span>）、以及每 SM 的常驻 CTA 数（occupancy）。三者关系是：SMEM 占用 ≈ <span>(B_q·d + B_k·d)·1 byte</span> 加上缩放因子与 softmax 状态，occupancy ≈ SMEM 总量 / 单 CTA 占用；而 FP8 MMA 的吞吐优势只有在 occupancy 足够、流水线能掩盖 TMA 延迟时才兑现。分块调得过小，occupancy 上去了但每块 MMA 形状太小、指令开销占比高；调得过大，occupancy 掉下来，TMA 延迟暴露，FP8 甚至慢于 BF16 内核——这正是失败模式里“occupancy 过低使 FP8 吞吐优势无法兑现”的机制来源。</p>\n<p>调度上还应把“批”理解为头维批：一次内核启动处理多个头，把头维并入 MMA 的 N 维或 M 维，可以在不增加 SMEM 的前提下提高算术强度。对视频扩散的单步前向，注意力调用是间歇性的，内核启动开销与尾块浪费需要靠持久化内核（persistent kernel）消化：固定数量的 CTA 常驻，从任务队列取头-块任务，避免每层重新调度。</p>\n<p>具体例子：单卡 B200 上，<span>B_q=128</span>、<span>B_k=256</span>、d=128 时单 CTA 的 SMEM 占用落在可容纳多 CTA 常驻的区间，配 2-SM MMA 后单次 MMA 形状翻倍，QK^T 吞吐接近 FP8 峰值；若把 <span>B_k</span> 提到 512 追求更高算术强度，SMEM 占用使 occupancy 减半，TMA 延迟无法被流水掩盖，实测反而退化——调度参数必须与 SM100 的 SMEM/TMEM 配额一起解，不能单独调。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-30\">三十 · 可复现的配置思路：从容量不等式倒推</h3>\n<p>把上述四维（硬件档位、并行拓扑、量化方案、KV 策略）与调度参数串成一条可复现的推导链，顺序是固定的：先由序列长度与头数算出 KV 字节需求，对照单卡 HBM 预算决定是否跨卡；再由跨卡决定拓扑（头并行优先，序列并行兜底）；再由尖峰统计决定量化分级（行级或分块缩放、回退通道比例）；再由展平顺序决定 KV 块形状与 TMA 描述符；最后由 SMEM 配额反解 <span>B_q</span>/<span>B_k</span> 与 occupancy 目标。每一步的输出是下一步的输入，任何一步跳过都会在长视频上暴露为延迟尖峰或数值塌缩。</p>\n<p>可复现性还要求把缩放因子与回退掩码作为配置的一部分固化下来：同一模型、同一分辨率下，行最大值缩放的统计应在校准阶段一次性算出并按层存储，运行时只做反缩放；回退通道掩码同理，按层按头固定，避免运行时动态判定带来的分支发散。这样内核在部署时的行为是确定的，SLO 可以按单步注意力时延与峰值显存两个指标做容量规划，而不必为数值路径的不确定性留余量。</p>\n<p>具体例子：一条 4K、数十帧的生成请求，按上述链条推得：KV 需求超单卡预算 → 8 卡头并行、每卡 4 头 → 尖峰层 1/8 通道 BF16 回退、其余分块缩放 E4M3 → 空间内层展平、<span>B_k=256</span> → 持久化内核配 2-SM MMA。这套配置在 NVL72 上可整组复制，唯一随分辨率变化的是 KV 块数与分块窗口，缩放因子与掩码随模型固定——这就是把部署配方写成可复现流程而非调参经验的意义。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-31\">三十一 · 配置边界：FP8 时空注意力内核的失效条件与系统代价</h3>\n<p>这套配方有明确的适用边界：它只在注意力路径上做 FP8 量化，Q/K/V 以 E4M3 存储、QK 与 PV 走 FP8 MMA、PV 累加保持 FP32，输出反缩放回 BF16 供后续 MLP 与残差使用，不改模型结构即可替换 BF16 内核。一旦序列变长到分块无法覆盖、或跨帧展平顺序与 HBM 访存合并冲突，收益就会反转。量化误差的放大条件可写成 <span class=\"formula\">$$ \\text{err}\\propto 2^{-4}\\lVert Q\\rVert\\lVert K\\rVert $$</span>，即误差随 Q、K 的范数增长，在 softmax 尖峰处被指数放大——表现为注意力权重塌缩、细节丢失。此时必须保留部分高精度通道或做混合精度回退，代价是这部分通道退回 BF16 吞吐，整体加速比按通道占比线性折损。</p>\n<p>并行拓扑与分块参数必须一起定。分块大小受 SM100 的 SMEM 容量约束，块越大 SMEM 占用越高、occupancy 越低；occupancy 不足时 FP8 MMA 的吞吐优势无法兑现，内核甚至慢于 BF16。跨帧注意力展平顺序若不当，分块加载 K/V 时 HBM 访存合并被破坏，带宽利用率骤降，长视频分块边界处延迟明显上升。因此配方应把展平顺序（时间优先还是空间优先）与块形状绑定调优，而不是沿用通用 FlashAttention 的默认排布。</p>\n<p>调度参数上，批大小按头数与序列分块配置，SLO 以单步注意力时延与峰值显存衡量。显存从 O(N^2) 降到 O(N) 是这套方案最硬的收益，但它是用在线 softmax 的 running 更新换来的：<span class=\"formula\">$$ m^{\\text{new}}=\\max(m,\\ \\max_j s_j),\\quad \\ell^{\\text{new}}=e^{m-m^{\\text{new}}}\\ell+\\sum_j e^{s_j-m^{\\text{new}}} $$</span>，每块都要重算归一化因子，块数增多时这部分标量开销不可忽略。序列极长时仍需配合长视频分块与重叠策略，重叠区带来的重复计算是显式代价。工程判断是：分辨率与帧数较大、注意力占主导时延的视频扩散模型才值得上这套配方；注意力占比低时，FP8 内核的调优成本换不回吞吐。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>softmax 尖峰处 P 量化误差放大</td><td>权重塌缩、细节丢失</td><td>保留高精度通道或混合精度回退</td></tr><tr><td>跨帧展平顺序不当</td><td>HBM 带宽利用率骤降、边界延迟上升</td><td>展平顺序与块形状绑定调优</td></tr><tr><td>分块过大、SMEM 占用高</td><td>occupancy 低，FP8 吞吐优势落空</td><td>按 SM100 SMEM 容量反推块大小</td></tr></tbody></table>\n<h3 id=\"alg-fp8-attn-video-sec-32\">三十二 · 显存账本：O(N²) 消失之后，谁成了新的地板</h3>\n<p>FP8 时空注意力把注意力自身的显存从 O(N²) 压到 O(N)，但这条曲线只描述 K/V 分块流式加载的那一段。真实驻留量由三块拼成：Q/K/V 的 FP8 副本（每元素 1 字节）、每头每查询行的行级缩放因子、以及 PV 的 FP32 累加器。累加器不进 HBM 而压在寄存器与 TMEM 上，它才是分块大小真正的上限约束——分块越大，在线 softmax 的 running max 与归一化因子越多，累加器占用随分块线性上升，SMEM 与 TMEM 很快被吃满。工程判断很直接：序列长度翻倍时，K/V 流式读取的带宽压力线性上升，而 Q 与输出写回的显存压力也线性上升，唯独注意力分数矩阵不再驻留。于是规模上去以后，第一个崩的往往不是显存容量，而是<strong>有效带宽</strong>——因为 O(N) 的流式读写在长序列下变成主导项，而它无法被分块复用摊薄。</p>\n<p>把驻留量写成可核算的形式：设头数为 H、头维 d、序列长 N、分块 B，则单层注意力驻留约为 3·H·N·d 字节（FP8 的 Q/K/V）加上 H·N 个缩放因子与 H·N·d 的 FP32 累加器折算。当 N 增长到让 3·H·N·d 逼近单卡 HBM 的可用余量时，KV 分块再小也救不了——因为 Q 与输出必须整段驻留。此时唯一出路是把序列沿时间-空间展平后切段，跨段做重叠，代价是边界处的重复计算。</p>\n<p>具体例子：一条 720p、数十帧的潜变量序列展平后 N 达到数十万量级，单层 FP8 的 Q/K/V 副本已占数百 MB 量级，多层叠加后单请求驻留进入 GB 级；此时若批大小仍按短序列配置，显存先于算力告急。核算方法不是猜，而是按 3·H·N·d 逐层累加，再与可用 HBM 减去权重与激活余量做差。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-33\">三十三 · 带宽与访存合并：展平顺序决定吞吐上限</h3>\n<p>FP8 让 QK 与 PV 的 MMA 吞吐翻倍，但翻倍的前提是数据能以合并方式喂进 SMEM。时空注意力的序列是沿时间-空间展平得到的，若展平顺序把相邻 token 在 HBM 中打散，分块加载 K/V 时每次 128B 事务只能取到零星有效元素，带宽利用率骤降，FP8 MMA 再快也只能空转。这是本算法区别于通用 FlashAttention 的关键约束：通用实现只需保证行内连续，时空展平则要求<strong>同一分块内的 token 在时间维与空间维上都保持局部性</strong>，否则跨帧边界处的加载会退化成随机访存。</p>\n<p>可用的判据是分块内有效字节率：设一次 K/V 分块加载触及 M 个 128B 事务，其中有效元素占比 ρ，则实际带宽需求为名义需求的 1/ρ。ρ 低于某个阈值时，FP8 相对 BF16 的吞吐增益被访存开销吃掉。工程做法是把展平顺序固定为「帧内空间优先、帧间次之」，让一个分块尽量落在同一帧或相邻两帧的连续区段；跨帧注意力需要显式重排索引，而不是依赖自然展平。</p>\n<p>代价体现在尾延迟上：长视频分块边界处，若展平顺序不当，边界分块的 ρ 最低，单步注意力时延出现尖峰，SLO 以单步时延衡量的服务会在这里抖动。具体例子：一条跨帧注意力占比高的序列，边界分块的加载事务数可达内部块的数倍，表现为该步时延明显高于均值——这不是算力问题，是访存合并被破坏。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-34\">三十四 · 通信：分离式部署下注意力内核的接口成本</h3>\n<p>在预填/解码分离的服务形态里，时空注意力内核不是孤立执行的：它要与 KV 传输、批调度、以及跨节点的专家或层切分对齐。FP8 的价值在这里被放大——Q/K/V 以 E4M3 存储使跨节点搬运的字节数减半，KV 传输带宽压力直接下降；但代价是接收端必须保留行级缩放因子并做反缩放，缩放因子的搬运是额外的元数据流量，头数与序列越长，这部分开销越不可忽略。NVLink 5 的高带宽能吸收主体流量，缩放因子与索引重排的元数据则走另一条路径，二者的配比决定通信是否成为瓶颈。</p>\n<p>通信代价可用一个简单比值判断：设单次注意力步的 KV 传输量为 S 字节、元数据为 s 字节，则有效载荷率为 S/(S+s)。当 s 随头数线性增长而 S 随分块线性增长时，小分块配置下有效载荷率恶化。工程判断是：分块不能只为 SMEM 占用调优，还要为通信有效载荷率设下限；跨节点场景下宁可增大分块、牺牲部分 occupancy，也要把元数据摊薄。</p>\n<p>具体例子：NVL72 机架内做层切分时，注意力输出需反缩放写回 BF16 再进入后续 MLP 与残差，这一步的写回量与 Q 同量级；若切分点落在注意力之后，写回流量与 KV 传输流量叠加，成为该层的通信主项。把切分点放在注意力之前、让 FP8 的 Q/K/V 直接跨节点，是更省的选择。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-35\">三十五 · 功耗与占用率：FP8 MMA 兑现不了的两个前提</h3>\n<p>FP8 MMA 的吞吐优势不是无条件兑现的。第一个前提是 occupancy：分块大小与 SMEM 占用未针对 SM100 调优时，驻留 warp 数不足，MMA 流水填不满，实测甚至慢于 BF16 内核。第二个前提是功耗预算：FP8 计算单元在高占用率下功耗密度上升，若机架功耗封顶，持续高 occupancy 会触发降频，吞吐回落。这两个前提互相拉扯——提高 occupancy 要减小分块，减小分块又恶化通信有效载荷率与访存合并。</p>\n<p>把吞吐写成可核算的形式：设单 SM 的 FP8 MMA 峰值吞吐为 T_peak，实际占用率为 u，则有效吞吐约为 u·T_peak；u 由 SMEM 占用与寄存器压力决定，而功耗封顶把 T_peak 本身按频率缩放。工程上要同时盯两个数：occupancy 是否足以填满 MMA 流水，以及持续负载下频率是否稳定。前者靠分块与 SMEM 调优，后者靠批调度把尖峰摊平——连续批处理在这里的作用不是提高平均吞吐，而是避免瞬时功耗尖峰触发降频。</p>\n<p>具体例子：同一内核在短序列、高分块配置下 occupancy 高但 SMEM 逼近上限，长序列下被迫减小分块，occupancy 反而下降；此时若批大小不变，单步时延上升而功耗不降，形成「慢且费」的组合。判断依据是实测 occupancy 与频率曲线，而不是理论峰值。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-36\">三十六 · 尾延迟：尖峰从哪里来，往哪里压</h3>\n<p>时空注意力的尾延迟有三个可定位的来源。其一是 softmax 尖峰处的 P 量化误差：P 量化为 E4M3 后，尖峰处误差被放大，表现为注意力权重塌缩与细节丢失；工程上用保留部分高精度通道或混合精度回退来压，回退路径本身带来分支与额外带宽，是尾延迟的隐性成本。其二是跨帧展平顺序不当造成的边界分块访存退化，表现为该步时延尖峰。其三是分块边界处的重复计算——长序列切段重叠时，重叠区的注意力被算两遍，重叠比例直接乘在时延上。</p>\n<p>尾延迟的核算可以写成：设 P99 步时延由主体时延 D 与尖峰增量 Δ 组成，Δ 来自上述三者之一；则服务容量规划要按 D+Δ 而非 D 配置。压 Δ 的手段按性价比排序：先修展平顺序（零额外算力），再调分块使边界 ρ 不低于内部块，最后才动混合精度回退（有算力代价）。</p>\n<p>具体例子：一条长视频请求在跨帧边界处分块，若重叠比例设为边界帧数的一小部分，重叠区重复计算量可控；但若展平顺序使边界块 ρ 骤降，单步时延尖峰远超重叠带来的增量，此时先修顺序比调重叠更有效。SLO 以单步注意力时延与峰值显存衡量时，尾延迟的预算应显式留给 Δ，而不是假设内核时延平稳。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-37\">三十七 · 规模上去以后，崩的顺序</h3>\n<p>把五条线放在一起，规模增长的崩溃顺序可以排出来。序列长度先撞上的是<strong>有效带宽</strong>：O(N) 的流式读写在长序列下成为主导，展平顺序不当使 ρ 下降，FP8 吞吐增益被访存吃掉。再往上撞的是<strong>驻留容量</strong>：Q 与输出必须整段驻留，3·H·N·d 逐层累加逼近 HBM 余量，此时只能切段重叠，重叠比例转化为时延。跨节点时撞的是<strong>通信有效载荷率</strong>：缩放因子与索引重排的元数据随头数增长，小分块配置下恶化。最后撞的是<strong>功耗与 occupancy 的互斥</strong>：为通信与访存调大分块，SMEM 逼近上限使 occupancy 下降，MMA 流水填不满，而功耗封顶又把频率压回去。</p>\n<p>工程判断因此是分层的：单卡内先保展平顺序与分块 ρ，再谈 FP8 吞吐；单机内先保驻留核算，再谈批大小；跨节点先保有效载荷率，再谈切分点位置；机架级先保功耗曲线平稳，再谈峰值 occupancy。每一层都有明确的核算量，而不是靠调参试错。FP8 时空注意力内核的收益在长序列、注意力占主导时延的视频扩散模型上最实，但它的规模上限不由 MMA 峰值决定，而由这条崩溃顺序里最先触顶的那一项决定——定位它，比优化它更重要。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-38\">三十八 · 规模上去以后，先崩的是带宽而不是算力</h3>\n<p>把FP8时空注意力放进真实推理链路，第一处失效点通常不在MMA吞吐，而在K/V分块的HBM供给。序列按时间-空间展平后，若展平顺序与张量物理布局不一致（例如先帧后块而非先块后帧），每个K/V块的有效加载会退化为跨步访问，合并度下降，带宽利用率骤降，FP8 MMA空转等待。此时即便算力翻倍也无意义：单步时延由<em>max(计算时间, K/V搬运时间)</em>决定，而后者随序列线性增长。以长视频高分辨率单步为例，注意力峰值显存从O(N²)降到O(N)确实缓解了容量压力，但每步仍需把整条K/V流式读一遍，带宽成为硬上限；分块边界处还要重读重叠区，重叠比例直接乘在带宽账单上。</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx\\max\\!\\left(\\frac{2N^{2}d}{P_{\\text{FP8}}},\\ \\frac{2N d\\,(1+\\rho)}{B_{\\text{HBM}}}\\right)$$</div>\n<p>其中ρ为分块重叠率，P_FFP8为有效MMA吞吐。当N增大，第二项先撞墙——这就是“规模上去先崩带宽”的定量表达。SMEM占用与分块大小未针对SM100调优时，occupancy过低会让第一项也兑现不了，出现FP8内核慢于BF16的反常。跨帧展平顺序不当是同一问题的另一种表现：合并失效使有效带宽打折，长视频分块边界延迟明显上升。</p>\n<h3 id=\"alg-fp8-attn-video-sec-39\">三十九 · 数值边界：尖峰处的量化误差与回退代价</h3>\n<p>误差量级由<div class=\"formula\">$$\\text{err}\\propto 2^{-4}\\lVert Q\\rVert\\lVert K\\rVert$$</div>给出，E4M3的4位尾数在softmax尖峰处最脆弱：当某行得分分布极尖，P矩阵大量元素落在极小值区，量化后相对误差被指数放大，表现为注意力权重塌缩与细节丢失。行级缩放与FP32累加只能抑制溢出与累加漂移，压不住尖峰处的相对误差。工程上的边界判断是：一旦检测到某头running max与次大得分差距超过阈值，该头回退BF16路径或保留高精度通道，代价是这部分头的吞吐回落、SMEM占用上升，并引入分支导致的warp发散——尾延迟由此抬升，因为回退头往往集中在少数关键帧。</p>\n<h3 id=\"alg-fp8-attn-video-sec-40\">四十 · 通信与尾延迟：并行切分后的新瓶颈</h3>\n<p>序列极长时单卡放不下，需配合长视频分块与重叠策略做序列并行，此时跨帧注意力的K/V需要跨设备交换。NVLink 5带宽虽高，但all-gather的通信量与序列长度成正比，且与计算不能完全重叠时，尾延迟由最慢的那个分块决定——分块负载不均（例如首帧含更多跨帧依赖）会放大长尾。功耗侧同样有边界：FP8 MMA吞吐翻倍的代价是单位时间能耗上升，机架功率封顶时持续高occupancy反而触发降频，使实际吞吐低于标称。容量规划应把“带宽受限区”和“功率受限区”分开建模，而不是用一个峰值算力数字覆盖全部规模区间。</p>\n<table class=\"mini\"><thead><tr><th>规模区间</th><th>先崩的资源</th><th>表征</th></tr></thead><tbody><tr><td>中等序列</td><td>SMEM/occupancy</td><td>FP8 MMA吞吐未兑现</td></tr><tr><td>长序列</td><td>HBM带宽</td><td>K/V搬运主导单步时延</td></tr><tr><td>超长+多卡</td><td>互联与负载均衡</td><td>尾延迟由最慢分块决定</td></tr></tbody></table>\n<h3 id=\"alg-fp8-attn-video-sec-41\">四十一 · 精度失败的三条路径与可观测信号</h3>\n<p>FP8时空注意力内核的精度失效不是单一现象，而是沿三条独立路径发生，诊断时必须分开归因。第一条是<strong>行级缩放失配</strong>：Q/K按行最大值缩放到E4M3后，若某行存在远大于其余元素的离群值，缩放因子被该离群值主导，其余元素落入E4M3的低位区间，尾数有效位被压缩，QK^T得分出现系统性偏差。第二条是<strong>softmax尖峰处的P量化误差放大</strong>：P量化为E4M3时，权重分布若集中在少数token上，尖峰元素的相对误差被归一化分母放大，表现为注意力权重塌缩——视觉上对应细节纹理丢失、运动边界模糊。第三条是<strong>PV累加路径的舍入累积</strong>，虽然累加器保持FP32，但P的量化误差在长序列上逐块累加，误差随分块数线性增长，公式上可写成 err ∝ 2^{-4}‖Q‖‖K‖ 的逐块叠加。</p>\n<p>可观测信号要落到具体张量上，而不是只看loss曲线。工程上建议在内核里挂三个探针：其一，每头每步的<strong>行缩放因子分布</strong>，统计max/median比值，比值超过阈值说明离群行出现，该头的QK^T可信度下降；其二，softmax输出的<strong>最大权重与熵</strong>，尖峰步的max权重突然抬升而熵骤降，是权重塌缩的前兆；其三，PV输出与BF16参考路径的<strong>逐块相对误差</strong>，按分块索引记录，若误差在跨帧边界块上跳变，则指向展平顺序而非量化本身。这三条信号分别对应缩放、softmax、累加三个环节，避免把精度问题误判为访存问题。</p>\n<p>代价层面，精度诊断本身要占资源：保留BF16参考路径做逐块比对，等于把注意力计算跑两遍，单步时延翻倍、显存多一份BF16的Q/K/V副本。因此生产环境不应全量开参考路径，而是按头采样——每层抽1–2个头做双跑比对，采样率控制在个位数百分比，把诊断开销压在单步时延的百分之几量级。回滚策略对应三条路径：缩放失配走<strong>保留高精度通道</strong>（对离群头单独走BF16 QK^T），尖峰塌缩走<strong>P的混合精度回退</strong>（尖峰块P不量化、直接以BF16参与PV），累加误差走<strong>分块重排</strong>（缩短单次累加链长度）。三者都是头级或块级粒度，不需要整模型回退BF16。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-42\">四十二 · OOM的真实来源：不是权重，是分块与副本</h3>\n<p>FP8注意力把显存从O(N^2)降到O(N)，但OOM仍会发生，来源往往不在Q/K/V本体。第一来源是<strong>SMEM与寄存器压力导致的occupancy塌陷</strong>：分块大小调大后，单块的K/V tile与P tile挤占SMEM，SM100上每个SM可驻留的CTA数下降，编译器为容纳tile而抬高寄存器上限，occupancy过低时FP8 MMA的吞吐优势无法兑现，内核甚至慢于BF16版本——此时显存没爆，但有效吞吐崩了，调度器为维持SLO而堆高并发批，反而把显存推爆。第二来源是<strong>跨帧展平顺序不当引发的临时缓冲膨胀</strong>：时间-空间展平后若K/V块的加载顺序与HBM合并访问不匹配，内核被迫物化中间重排缓冲，这部分缓冲随序列长度线性增长，且不在显存预算表里。第三来源是<strong>诊断副本</strong>：BF16参考路径、逐块误差记录、行缩放因子直方图，这些监控张量若按步累积而不做环形缓冲，会在长视频推理中缓慢吃掉预留显存。</p>\n<p>诊断OOM要区分“瞬时峰值”与“稳态泄漏”。瞬时峰值看单步内的显存水位曲线，重点观察分块边界处的尖峰——跨帧边界块加载时若同时驻留前后两个tile，峰值等于两倍tile。稳态泄漏看跨步的基线漂移，若每步基线抬升固定量，几乎必然是监控缓冲未回收或KV副本未释放。工程判断上，分块大小应作为<strong>受SMEM约束的一等配置项</strong>暴露出来，而不是编译期常量：SM100的SMEM容量固定，分块调优的目标是在occupancy与单块效率之间取平衡点，配置错误时表现为“显存够但吞吐不达标”，此时正确动作是降分块而非加批。</p>\n<p>回滚路径按来源分：occupancy塌陷回滚到<strong>较小分块+更多CTA</strong>的组合；展平顺序问题回滚到<strong>按帧优先的加载序</strong>，牺牲部分合并度换缓冲消除；监控泄漏回滚到<strong>环形缓冲+按步采样</strong>。三者都不触碰模型结构，符合本内核“可直接替换BF16注意力”的定位。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-43\">四十三 · 批抖动与路由不均：调度层的两类噪声</h3>\n<p>批抖动指连续批处理下，单步时延随批内序列长度分布剧烈波动。时空注意力的序列长度随分辨率与帧数平方增长，批内若混入一条4K长视频与若干短片段，长序列请求的分块数远多于短请求，单步内各请求的CTA占用不均，短请求早早完成而长请求拖尾，形成<strong>批内完成时间方差</strong>。抖动放大到服务层表现为吞吐随批组成漂移，容量规划失效。诊断信号是<strong>批内各请求的分块完成时间分布</strong>与<strong>批组成的序列长度直方图</strong>，两者联立可判断抖动是来自批组成还是来自单请求内部的分块不均。</p>\n<p>路由不均发生在多头并行与多卡切分场景：头按卡切分后，若某些头的行缩放因子分布更极端（离群行多），这些头的QK^T需要更多高精度回退，计算量高于其他头，形成<strong>头级负载偏斜</strong>。跨卡时偏斜表现为部分卡先完成、部分卡空转，NCCL集合通信等待最慢卡，尾延迟被拉长。诊断信号是<strong>每头每步的高精度回退比例</strong>与<strong>每卡的MMA占用率</strong>，回退比例高的头即偏斜源。公式上可把单步时延写成 T = max_h(T_h) 而非均值，偏斜直接决定尾延迟。</p>\n<p>代价上，批抖动与路由不均都直接体现为<strong>尾延迟尖刺</strong>：P99时延远高于P50，且尖刺与批组成或头分布相关而非随机。回滚策略是调度层的：批抖动走<strong>按序列长度分桶</strong>，长视频请求单独成批，避免与短请求混排；路由不均走<strong>头级动态回退预算</strong>，给偏斜头分配更多BF16通道配额，或把偏斜头重映射到负载较轻的卡。两者都不改内核代码，属于部署配方的调整项。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-44\">四十四 · 尾延迟尖刺的定位：分块边界与跨帧展平</h3>\n<p>尾延迟尖刺在本内核里有明确的机制来源：<strong>跨帧注意力展平顺序不当</strong>。时空序列沿时间-空间展平后，分块加载K/V时若块边界落在帧切换处，相邻块的HBM访问模式突变，合并度下降，带宽利用率骤降，该块的加载时延显著高于帧内块。长视频分块边界处延迟上升是已知代价，但尖刺若集中在少数块上，说明展平顺序与分块大小未对齐帧边界。诊断方法是按分块索引记录<strong>加载时延与带宽利用率</strong>，若尖刺块索引与帧边界重合，即可确认。</p>\n<p>第二类尖刺来自<strong>softmax在线更新的running max跳变</strong>：新块的最大得分远超历史running max时，归一化因子重算，该步的softmax开销抬升。这在长视频中表现为偶发的单步尖刺，频率随序列长度增加。诊断信号是<strong>running max的更新幅度直方图</strong>，幅度大的步即尖刺候选。第三类是<strong>occupancy边界效应</strong>：分块大小恰好使某SM的CTA数落在阈值边缘，调度抖动导致个别步的MMA占用率骤降。</p>\n<p>三类尖刺的代价都落在P99而非均值上，监控必须按分块索引与步索引双维度聚合，而不是只看服务级P99。回滚路径：帧边界尖刺回滚到<strong>帧对齐分块</strong>，把分块大小取为帧内token数的整数倍；running max跳变回滚到<strong>分块内预扫描</strong>，先算块内最大得分再更新，代价是少量额外寄存器；occupancy边界回滚到<strong>分块大小取整到SMEM容量的整除因子</strong>。这些回滚都是配置级，可在不重编译内核的前提下通过参数切换。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-45\">四十五 · 监控体系与回滚闸门</h3>\n<p>监控要覆盖四个维度且各自有明确阈值语义：<strong>精度</strong>（行缩放max/median比、softmax熵、逐块相对误差）、<strong>显存</strong>（单步峰值水位、跨步基线漂移、诊断缓冲占用）、<strong>吞吐</strong>（MMA占用率、带宽利用率、分块完成时间方差）、<strong>尾延迟</strong>（按分块与步索引聚合的P99）。四类信号按头、按块、按步三级粒度打点，采样率分级：精度探针按头采样，显存与吞吐全量，尾延迟按块索引全量但只保留环形窗口。</p>\n<p>回滚闸门的设计原则是<strong>粒度尽量细、触发尽量早</strong>。精度闸门挂在头级：某头行缩放比超阈值即对该头启用BF16 QK^T通道，不等待服务级精度指标恶化。显存闸门挂在分块级：单步峰值逼近预算时自动降分块，而非等OOM后重启。吞吐闸门挂在卡级：MMA占用率持续低于基线时触发分块重调优。尾延迟闸门挂在批级：P99尖刺与批组成相关时触发分桶重排。四级闸门互不阻塞，任一级触发只影响对应粒度，避免一次精度告警引发全模型回退BF16的过度反应。</p>\n<p>工程判断上，最容易被忽视的是<strong>诊断开销本身成为尖刺源</strong>：逐块误差记录若同步写回主机，会在分块边界引入额外同步点，恰好放大帧边界尖刺。正确做法是探针数据留在SMEM或寄存器中异步聚合，按步批量导出。另一个判断是回滚闸门必须有<strong>滞回</strong>：头级BF16通道启用后需连续若干步精度恢复才关闭，否则会在阈值附近反复切换，切换本身带来批抖动。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-46\">四十六 · 失败模式与配置项的对应表</h3>\n<p>把前述失败模式收敛成一张可操作的对应表，是诊断流程的落点。表中每一行是一个可观测现象、其机制归因、对应配置项与回滚动作，工程上按现象查表即可，不需要每次从公式重新推导。</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>机制归因</th><th>配置项</th><th>回滚动作</th></tr></thead><tbody><tr><td>细节纹理丢失、运动边界模糊</td><td>P量化误差在softmax尖峰放大</td><td>P混合精度回退比例</td><td>尖峰块P走BF16参与PV</td></tr><tr><td>单头QK^T得分系统性偏差</td><td>行级缩放被离群值主导</td><td>头级高精度通道配额</td><td>该头QK^T走BF16</td></tr><tr><td>显存够但吞吐不达标</td><td>分块过大致occupancy塌陷</td><td>分块大小、SMEM占用</td><td>降分块、增CTA数</td></tr><tr><td>帧边界块加载时延尖刺</td><td>展平顺序破坏HBM合并</td><td>展平顺序、分块对齐</td><td>帧对齐分块、帧优先加载</td></tr><tr><td>批内完成时间方差大</td><td>批组成序列长度不均</td><td>批分桶策略</td><td>长视频请求单独成批</td></tr><tr><td>部分卡空转、尾延迟拉长</td><td>头级负载偏斜</td><td>头到卡映射、回退预算</td><td>偏斜头重映射或加配额</td></tr><tr><td>跨步显存基线漂移</td><td>监控缓冲未回收</td><td>探针采样率、环形窗口</td><td>环形缓冲、按步批量导出</td></tr></tbody></table>\n<p>这张表的用法有两条约束。其一，现象与归因是多对多的，同一现象可能由两条路径叠加，例如细节丢失既可能来自P量化也可能来自行缩放失配，必须用头级探针先分离再回滚，不能直接套用表中最接近的一行。其二，回滚动作的粒度必须与归因粒度一致：头级归因走头级回滚，块级归因走块级回滚，跨级回滚会把局部问题扩散成全局性能损失。配置项应作为运行时可切换的参数暴露，使回滚在单步内生效而不中断服务。</p>\n<p>最后一条工程判断落在<strong>回退预算的显式化</strong>上：高精度通道与混合精度回退不是免费的，每启用一个头的BF16 QK^T，该头的吞吐相对FP8路径下降，回退比例上升会侵蚀FP8带来的吞吐翻倍收益。因此回退预算应按头分配并计入容量规划，把“精度换吞吐”的权衡从隐式变成显式配置，避免精度告警驱动的回退在长视频负载下悄悄吃掉全部吞吐余量。</p>\n<h3 id=\"alg-fp8-attn-video-sec-47\">四十七 · 同族算法的四条分界线</h3>\n<p>把FP8时空注意力内核放回它所在的算法族里，选择问题不是“用不用FP8”，而是四个正交维度的取舍：量化作用面（只动注意力路径，还是连线性层一起动）、序列组织方式（稠密展平，还是稀疏/分块重叠）、缓存策略（是否跨去噪步复用K/V）、精度回退粒度（整头回退，还是通道级保留）。本内核的定位是“作用面最窄、替换成本最低”的那一档：Q/K/V与P走E4M3，PV累加FP32，模型结构与权重格式不变，因此它可以作为一次纯内核替换上线，而不触发量化感知微调或权重重打包。相邻的NVFP4视频DiT量化推理动的是线性层权重与激活，收益在MLP与投影上，与本内核在时间轴上不重叠——两者叠加时，注意力段由本内核负责，线性段由NVFP4负责，中间以BF16残差衔接，这是最干净的组合方式。</p>\n<p>第二条分界线是序列组织。动态稀疏时空注意力削减的是参与计算的K/V块数量，把O(N²)的有效对砍到稀疏子集；本内核不削减对数，而是把每一对的成本从BF16压到FP8并把中间矩阵落盘消除。二者的代价结构不同：稀疏路线在低帧率、强局部相关的素材上收益大，但索引构建与负载不均衡会引入尾延迟；FP8路线收益与序列长度近乎线性，且对内容不敏感，尾延迟稳定。第三条是缓存复用：轨迹感知缓存复用跨步复用注意力输出，属于“减少调用次数”；本内核属于“降低单次调用成本”。二者相乘而非互斥，但复用率高的场景里单次成本被摊薄，FP8的边际收益会下降，此时应优先保证复用命中率而不是继续压精度。第四条是精度回退粒度，决定了本内核能否在尖峰分布上安全落地。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-48\">四十八 · 决策表：按约束选型</h3>\n<p>下表以工程约束为行、候选算法为列，给出“首选/次选/不适用”的判断。表中不写实验数字，只写机制层面的适用条件。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>约束条件</th><th>FP8时空注意力</th><th>NVFP4线性量化</th><th>动态稀疏注意力</th><th>缓存复用</th></tr>\n</thead>\n<tbody>\n<tr><td>注意力占单步时延主导</td><td>首选</td><td>次选（仅缓解投影）</td><td>首选（内容局部性强时）</td><td>不适用</td></tr>\n<tr><td>线性层/MLP占主导</td><td>次选</td><td>首选</td><td>不适用</td><td>不适用</td></tr>\n<tr><td>不允许改模型结构或权重</td><td>首选</td><td>不适用</td><td>次选（需索引模块）</td><td>首选</td></tr>\n<tr><td>softmax分布尖峰、细节敏感</td><td>需通道级回退</td><td>无关</td><td>次选</td><td>需校正机制</td></tr>\n<tr><td>序列极长、显存吃紧</td><td>首选（O(N)显存）</td><td>不适用</td><td>首选</td><td>次选</td></tr>\n<tr><td>去噪步间高度相似</td><td>次选</td><td>次选</td><td>次选</td><td>首选</td></tr>\n<tr><td>SMEM预算紧张、分块受限</td><td>需重调分块</td><td>无关</td><td>不适用</td><td>无关</td></tr>\n</tbody>\n</table>\n<p>读表方式是先定位主导项：用单步耗时剖面把注意力、线性、通信三段切开，若注意力段占比过半则本内核进入首选；若线性段占比过半则先上NVFP4，注意力段维持BF16或轻量FP8。第二列与第三列在“序列极长”行同时为首选，原因是二者削减的是不同量：本内核削的是每对成本与中间矩阵显存，稀疏削的是对数，长序列下二者可叠加，但叠加时要注意稀疏索引的构建本身也要读K，若K已是FP8则索引打分同样受益。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-49\">四十九 · 适用条件的量化判据</h3>\n<p>把“注意力是否主导”变成可计算的判据，用单步时间分解：设单步总时为T，注意力段为T<sub>attn</sub>，线性段为T<sub>lin</sub>，则本内核的预期收益上界为</p>\n<div class=\"formula\">$$\\text{speedup}_{\\max}\\approx\\frac{T}{T-T_{\\text{attn}}\\,(1-\\rho)},\\quad \\rho=\\frac{t_{\\text{FP8}}}{t_{\\text{BF16}}}$$</div>\n<p>其中ρ是单对QK/PV在FP8 MMA与BF16路径上的耗时比，由硬件吞吐决定而非由模型决定；T<sub>attn</sub>/T越大，收益越接近理论上界。这个式子的工程含义是：当注意力段占比不足三成时，即便ρ很小，端到端加速也被线性段与通信段稀释，此时应把工程预算投向线性量化或调度，而不是继续调注意力分块。反过来，若注意力段占比高且序列长度随分辨率与帧数平方增长，则T<sub>attn</sub>会随负载自然膨胀，本内核的收益随负载变重而变大——这是它与稀疏路线的重要区别，稀疏路线的收益依赖内容，负载变重不一定带来更高收益。</p>\n<p>第二个判据是显存。BF16下注意力中间矩阵随N²增长，本内核把显存压到O(N)，因此当N大到中间矩阵无法与权重共存于HBM时，本内核从“加速项”变成“可行性项”。判断阈值不是固定序列长度，而是“权重+激活+中间矩阵”的峰值是否越过单卡容量；越过即必须上分块在线softmax，此时FP8是顺带收益而非主因。第三个判据是数值：用校准集统计每个头的softmax最大概率p<sub>max</sub>与得分分布的峰度，p<sub>max</sub>接近1的头说明注意力高度集中，P量化为E4M3后尖峰处的相对误差被放大，这类头应列入通道级保留名单。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-50\">五十 · 组合与互斥：三条工程规则</h3>\n<p>规则一，精度作用面不重叠即可叠加。本内核管注意力路径，NVFP4管线性权重，二者以BF16残差衔接，叠加时不需要联合校准，只需保证QKV投影的输出缩放与本内核的行级缩放一致，否则会出现“投影输出已按NVFP4反量化、注意力又按另一套scale缩放”的双重缩放错位。规则二，削减对数与削减单对成本可叠加但有次序：先上本内核拿到稳定的O(N)显存与翻倍吞吐，再评估稀疏；反过来先稀疏会让索引构建依赖BF16的K，抵消一部分精度收益，且稀疏带来的负载不均衡会掩盖FP8内核的稳定尾延迟优势。规则三，缓存复用与本内核叠加时，复用命中率下降会同时放大两者的误差——复用输出本身是近似，FP8又引入P量化误差，二者在同一去噪步内累积。工程做法是把复用校正机制与本内核的回退名单对齐：被列入高精度通道的头，其复用输出也应走校正路径。</p>\n<p>互斥情形也要写清楚。当序列长度不足以让分块在线softmax摊薄开销时（短序列、小分辨率），本内核的启动开销与反缩放写回占比上升，此时BF16注意力内核的端到端表现不劣，强行替换只增加调优成本。当SMEM预算被其他算子挤占、分块只能取到很小值时，occupancy过低会让FP8 MMA的吞吐优势无法兑现，甚至慢于BF16内核——这不是精度问题而是调度问题，应先解决SMEM分配再谈精度。当模型对细节极其敏感且校准显示多个头p<sub>max</sub>接近1时，通道级回退的比例会高到抵消大部分收益，此时应转向稀疏路线或缓存复用，而不是硬推全FP8。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-51\">五十一 · 一个选型实例的推演</h3>\n<p>设一个高分辨率长视频扩散模型，单步剖面显示注意力段占六成、线性段占三成、通信与调度占一成，序列长度随帧数平方增长，单卡峰值显存已接近容量上限，且不允许改权重格式。按决策表：第一行“注意力主导”指向本内核；第三行“不改结构”排除NVFP4；第五行“显存吃紧”再次指向本内核。推演顺序为：先以分块在线softmax把中间矩阵显存从O(N²)降到O(N)，解决可行性；再在Q/K/V上启用E4M3与行级缩放，PV累加保持FP32，拿到QK与PV吞吐翻倍；随后用校准集统计各头p<sub>max</sub>，对尖峰头保留高精度通道，形成混合精度回退名单；最后评估是否叠加缓存复用，若复用命中率高则把校正机制与回退名单对齐。整个过程中不改模型结构，输出反缩放写回BF16供后续MLP与残差使用，线性段维持原精度等待后续NVFP4改造。</p>\n<p>若剖面改为线性段占六成、注意力段占两成，则推演顺序反转：先上NVFP4线性量化，注意力段维持BF16；待线性段压缩后注意力占比自然上升，再评估本内核。这个反转说明选型不是静态标签，而是随剖面移动的顺序问题——同一模型在不同分辨率、不同帧数、不同批大小下，主导项会切换，决策表应随负载配方重跑，而不是一次选定终身沿用。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-52\">五十二 · 选型的收敛判据</h3>\n<p>最终判断落在两个可测量量上：一是注意力段占单步总时的比例，二是峰值显存中中间矩阵的占比。前者决定本内核的加速上界，后者决定它是否从加速项变为可行性项。两个量都高时，本内核是唯一不需要改模型结构就能同时解决时延与显存的选择；前者高后者低时，本内核是纯加速项，可与稀疏或缓存复用叠加；前者低时，无论显存如何，工程预算应移向线性量化与调度。把这两个量纳入常规剖面采集，选型就从经验判断变成每次负载配方变更后的一次重算，而回退名单与分块参数则作为该次重算的附带产物固化进部署配置。</p>\n\n<h3 id=\"alg-fp8-attn-video-sec-53\">五十三 · 同族算法怎么选：FP8时空注意力的适用边界与失效条件</h3>\n<p>本方案与三类相邻算法最容易混淆：作用于线性层权重的NVFP4视频DiT量化、通用FlashAttention（BF16或FP8但不含时空展平约束）、以及长视频分块重叠策略。选择判据不是精度档位高低，而是瓶颈落在哪条路径上。若时延由MLP与投影权重带宽主导，注意力占比不高，则应优先NVFP4线性层量化，本方案收益有限；若序列长度中等、注意力已非主要瓶颈，通用FlashAttention的BF16内核在数值上更省心，引入FP8只增加回退分支与调优成本。本方案真正占优的条件是：分辨率与帧数推高序列长度、QK^T与PV成为单步时延主项、且模型结构不可改动——它只替换注意力内核，Q/K/V与P走E4M3，PV累加保持FP32，输出反缩放回BF16供MLP与残差使用。</p>\n<p>失效条件集中在两处。其一是P矩阵量化：E4M3在softmax尖峰附近的分辨率不足，权重塌缩表现为细节丢失，需保留高精度通道或整块回退BF16；误差量级可由<div class=\"formula\">$$\\text{err}\\propto 2^{-4}\\lVert Q\\rVert\\lVert K\\rVert$$</div>定性判断，行级缩放把$\\lVert Q\\rVert$、$\\lVert K\\rVert$压进E4M3动态范围，但压不住尖峰处的相对误差。其二是访存：跨帧展平顺序不当会破坏HBM合并访问，分块加载K/V时带宽利用率骤降，长视频分块边界延迟上升；分块大小受SMEM容量限制，未针对SM100调优时occupancy过低，FP8 MMA吞吐翻倍的优势兑现不了，甚至慢于BF16内核。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>首选</th><th>代价/风险</th></tr></thead><tbody><tr><td>注意力占主导、结构不可改</td><td>本方案（FP8 E4M3 + 在线softmax）</td><td>P量化回退分支、SMEM调优</td></tr><tr><td>权重带宽主导</td><td>NVFP4线性层量化</td><td>不触及注意力路径</td></tr><tr><td>序列中等、精度敏感</td><td>BF16 FlashAttention</td><td>显存仍O(N²)，无FP8吞吐增益</td></tr><tr><td>极长序列</td><td>本方案 + 长视频分块重叠</td><td>边界延迟、展平顺序约束</td></tr></tbody></table>\n<p>工程判断落在决策顺序上：先测单步注意力时延占比，再看峰值显存是否由O(N²)注意力项支配，两者同时成立才值得引入FP8路径；随后固定时间-空间展平顺序与分块尺寸，把SMEM占用与occupancy一起调，最后按头或按层保留少量高精度通道兜住softmax尖峰。任一条件不满足，回退BF16内核的端到端代价通常低于维持一条调优不充分的FP8分支。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · 稀疏时空注意力与流式长视频</td></tr><tr><td>解决什么</td><td>视频扩散的时空注意力序列长度随分辨率与帧数平方增长，BF16下注意力QK^T与PV成为主要时延与显存瓶颈。</td></tr><tr><td>一句话机制</td><td>在Blackwell上以FP8 E4M3存储Q/K/V并用分块在线softmax完成注意力，PV累加保持FP32，行级…</td></tr><tr><td>代价与失效</td><td>P矩阵量化误差在softmax尖峰处放大，需保留部分高精度通道或做混合精度回退；分块大小与SMEM占用需针对SM100调优，跨帧注意力展平…</td></tr><tr><td>后继</td><td>视频自回归投机解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-fp8-attn-video · 共 8 个片段</p>\n";break;}}})();
